    #[tokio::test]
    async fn runtime_links_required_baked_system_provider_roles_at_open() {
        let (_temp, repository) = repository();
        let state = open_state(&repository).await;
        let invoke = state
            .system_provider_roles()
            .resolve("langitem.sys.invoke")
            .unwrap();
        assert_eq!(invoke.provider.as_str(), "orna.sys.v1");

        let checkout = state
            .system_operation_contract("sys.admin.checkout(SnapshotRef)")
            .expect("runtime resolves operations from the generated dispatch table");
        assert!(!checkout.preconditions.is_empty());
        let mut checked = Vec::new();
        let admitted = state
            .check_system_operation_preconditions(checkout.id.as_str(), |precondition| {
                checked.push(precondition.declaration.clone());
                Ok(())
            })
            .expect("native handler may run after every registered precondition passes");
        assert_eq!(checked.len(), checkout.preconditions.len());
        assert_eq!(admitted.id, checkout.id);

        let precondition_failure = orna_sys::FailureCode::new("sys.abi.precondition_failed")
            .expect("shared precondition failure code is valid");
        assert!(
            state
                .validate_system_failure(checkout.id.as_str(), &precondition_failure)
                .is_ok()
        );

        let dispatched = state
            .dispatch_system_operation(
                checkout.id.as_str(),
                |_| Ok(()),
                |contract| {
                    assert_eq!(contract.id, checkout.id);
                    Ok(7)
                },
            )
            .expect("runtime dispatch uses the selected generated contract");
        assert_eq!(dispatched, orna_sys::SystemDispatchResult::Returned(7));

        let mut native_handler_ran = false;
        let rejected = state
            .dispatch_system_operation(
                checkout.id.as_str(),
                |_| Err(precondition_failure.clone()),
                |_| {
                    native_handler_ran = true;
                    Ok(())
                },
            )
            .expect("a declared precondition failure is returned at the boundary");
        assert_eq!(
            rejected,
            orna_sys::SystemDispatchResult::Failed(precondition_failure.clone())
        );
        assert!(
            !native_handler_ran,
            "failed checks must stop native dispatch"
        );

        let undeclared_failure = orna_sys::FailureCode::new("sys.storage.corrupt")
            .expect("failure code syntax is valid");
        assert!(matches!(
            state.dispatch_system_operation(
                checkout.id.as_str(),
                |_| Ok(()),
                |_| Err::<(), _>(undeclared_failure.clone()),
            ),
            Err(orna_sys::ProviderDiagnostic::UndeclaredFailure { .. })
        ));
        assert!(matches!(
            state.validate_system_failure(checkout.id.as_str(), &undeclared_failure),
            Err(orna_sys::ProviderDiagnostic::UndeclaredFailure { .. })
        ));
        assert!(matches!(
            state.check_system_operation_preconditions(checkout.id.as_str(), |_| {
                Err(precondition_failure.clone())
            }),
            Err(orna_sys::ProviderDiagnostic::PreconditionFailed { .. })
        ));
    }

    #[tokio::test]
    async fn history_migration_seeds_current_rows_and_marks_older_generations_incomplete() {
        let (_temp, repository) = repository();
        let state = open_state(&repository).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let first_context = state.begin_activation().await.unwrap();
        state
            .commit_table_activation(
                writer,
                &first_context,
                &[
                    table_mutation(5, 1, Some(11)),
                    table_mutation(6, 2, Some(22)),
                ],
                digest(7),
                &NoFault,
            )
            .await
            .unwrap();
        let second_context = state.begin_activation().await.unwrap();
        state
            .commit_table_activation(
                writer,
                &second_context,
                &[table_mutation(8, 1, Some(33))],
                digest(9),
                &NoFault,
            )
            .await
            .unwrap();

        // Simulate an existing database from before the history migration.
        // Its current row image is known, but generation 1's row image is not.
        let transaction = state.connection.transaction().await.unwrap();
        transaction
            .execute("DELETE FROM runtime_table_history", ())
            .await
            .unwrap();
        transaction
            .execute("DELETE FROM runtime_table_history_metadata", ())
            .await
            .unwrap();
        transaction.commit().await.unwrap();
        drop(state);

        let reopened = open_state(&repository).await;
        assert_eq!(
            reopened.select_historical_snapshot(1).await.unwrap_err(),
            RuntimeError::SnapshotIncomplete
        );
        let latest = reopened.select_historical_snapshot(2).await.unwrap();
        assert_eq!(
            reopened
                .read_table_at(&latest, "books")
                .await
                .unwrap()
                .rows(),
            &[(vec![1], vec![33]), (vec![2], vec![22])]
        );
    }

    async fn begin_continuable_request(
        state: &RuntimeState,
        owner: WriterLease,
        session: u8,
        request_id: u8,
        fingerprint_value: u8,
    ) -> (RequestIdentity, [u8; 32], RunObservation) {
        let identity = request(session, request_id);
        let fingerprint = digest(fingerprint_value);
        let run = state
            .begin_observed_request(
                RunObservationRegistration {
                    request: identity,
                    consumer_identity: stream_delivery("continuation", "admission").consumer,
                    function: "pkg.continuation".into(),
                    source_identity: Some("table books".into()),
                    invocation_id: id(request_id.wrapping_add(1)),
                },
                fingerprint,
                owner,
            )
            .await
            .unwrap()
            .run
            .unwrap();
        (identity, fingerprint, run)
    }

    fn activation_catalogue(predecessor: Option<CwdCapture>, revision: u8) -> CatalogueAdmission {
        CatalogueAdmission {
            predecessor_capture: predecessor,
            types: vec![CatalogueTypeDeclaration {
                declaration: CatalogueDeclaration {
                    qualified_name: "pkg.Result".into(),
                    kind: CatalogueObjectKind::Type,
                    revision_id: digest(180),
                    semantic_hash: digest(181),
                    rename_from: None,
                },
                form: CatalogueTypeSpec::Named,
            }],
            functions: vec![CatalogueFunctionDeclaration {
                declaration: CatalogueDeclaration {
                    qualified_name: "pkg.activate".into(),
                    kind: CatalogueObjectKind::Function,
                    revision_id: digest(revision),
                    semantic_hash: digest(revision),
                    rename_from: None,
                },
                parameters: Vec::new(),
                result_type_name: "pkg.Result".into(),
            }],
        }
    }

    #[tokio::test]
    async fn combined_catalogue_activation_success_source_only_reopen_and_replay() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let initial = state.capture().await.unwrap();
        let admitted = state
            .admit_catalogue_at(writer, &initial, activation_catalogue(None, 182))
            .await
            .unwrap();
        let old_function = admitted.functions[0].clone();
        let mut expected_rows = Vec::new();
        for (index, source_only) in [false, true].into_iter().enumerate() {
            let (identity, fingerprint, _) =
                begin_continuable_request(&state, writer, 60, 61 + index as u8, 65 + index as u8)
                    .await;
            let context = state.begin_activation().await.unwrap();
            let admission =
                activation_catalogue(Some(context.capture().clone()), 183 + index as u8);
            let mutations = if source_only {
                Vec::new()
            } else {
                expected_rows.push((vec![1], vec![9]));
                vec![table_mutation(70, 1, Some(9))]
            };
            let mut validator = ObservingTableActivationValidator {
                tables: vec!["books".into()],
                calls: 0,
                seen: None,
            };
            let committed = state
                .commit_validated_catalogue_table_request_activation(
                    ValidatedTableRequestActivationCommit {
                        writer,
                        identity,
                        fingerprint,
                        context: &context,
                        mutations: &mutations,
                        next_digest: digest(80 + index as u8),
                        outcome: outcome(90),
                        validator: &mut validator,
                        faults: &NoFault,
                        effects: orna_evaluator::EffectGate::admit_unbound_for_test(),
                    },
                    &admission,
                )
                .await
                .unwrap();
            assert_eq!(
                committed.capture.generation(),
                &(context.capture().generation() + BigInt::from(1))
            );
            assert_eq!(committed.request.terminal_outcome, Some(outcome(90)));
            assert_eq!(validator.seen.unwrap().get("books"), Some(&expected_rows));
            let function = state
                .catalogue_function("pkg.activate")
                .await
                .unwrap()
                .unwrap();
            assert_eq!(function.object.object_id, old_function.object.object_id);
            assert_eq!(function.object.revision_id, digest(183 + index as u8));
            assert_eq!(
                state
                    .catalogue_function_at("pkg.activate", &initial)
                    .await
                    .unwrap(),
                Some(old_function.clone())
            );

            let pending = state.pending().await.unwrap();
            let event = pending.last().unwrap();
            let value = Value::decode(&event.payload).unwrap();
            let OvbRaw::Array(fields) = value.raw() else {
                panic!("catalogue event must be structural")
            };
            assert_eq!(
                fields[0],
                OvbRaw::Text("orna.runtime.catalogue-change.v1".into())
            );
            assert_eq!(fields[3], committed.capture.snapshot().raw());
            assert_eq!(
                state
                    .latest_checkpoint()
                    .await
                    .unwrap()
                    .unwrap()
                    .mutation_sequence,
                2 + index as u64
            );

            // Invalid new inputs and a rejecting validator cannot cause a
            // matching terminal request to re-execute or re-admit identities.
            let mut rejecting = RejectingValidator {
                tables: Vec::new(),
                calls: 0,
            };
            let replay = state
                .commit_validated_catalogue_table_request_activation(
                    ValidatedTableRequestActivationCommit {
                        writer,
                        identity,
                        fingerprint,
                        context: &context,
                        mutations: &[],
                        next_digest: digest(0),
                        outcome: outcome(99),
                        validator: &mut rejecting,
                        faults: &Fail(FaultPoint::BeforeTableWrite),
                        effects: orna_evaluator::EffectGate::admit_unbound_for_test(),
                    },
                    &activation_catalogue(None, 199),
                )
                .await
                .unwrap();
            assert_eq!(replay, committed);
            assert_eq!(rejecting.calls, 0);
            assert_eq!(state.pending().await.unwrap(), pending);
        }
        let capture = state.capture().await.unwrap();
        let checkpoint = state.latest_checkpoint().await.unwrap();
        drop(state);
        let reopened = open_state(&repo).await;
        assert_eq!(reopened.capture().await.unwrap(), capture);
        assert_eq!(reopened.latest_checkpoint().await.unwrap(), checkpoint);
        assert_eq!(
            reopened.committed_table_row("books", &[1]).await.unwrap(),
            Some(vec![9])
        );
        assert_eq!(
            reopened
                .catalogue_function("pkg.activate")
                .await
                .unwrap()
                .unwrap()
                .object
                .revision_id,
            digest(184)
        );
        assert_eq!(
            reopened
                .catalogue_function_at("pkg.activate", &initial)
                .await
                .unwrap(),
            Some(old_function)
        );
        assert_eq!(
            reopened
                .request_status(request(60, 62), digest(66))
                .await
                .unwrap()
                .unwrap()
                .terminal_outcome,
            Some(outcome(90))
        );
    }

    #[tokio::test]
    async fn combined_catalogue_activation_rollback_and_writer_fencing() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let (identity, fingerprint, _) =
            begin_continuable_request(&state, writer, 100, 101, 102).await;
        let context = state.begin_activation().await.unwrap();
        let admission = activation_catalogue(Some(context.capture().clone()), 182);
        let mutations = [table_mutation(103, 1, Some(9))];
        for point in [
            FaultPoint::BeforeTableWrite,
            FaultPoint::AfterTableWrite,
            FaultPoint::AfterMutation,
            FaultPoint::AfterCheckpoint,
            FaultPoint::AfterCapture,
            FaultPoint::BeforeTerminalClaim,
            FaultPoint::AfterTerminalClaim,
        ] {
            let (identity, fingerprint, run) = begin_continuable_request(
                &state,
                writer,
                110 + point as u8,
                130 + point as u8,
                150 + point as u8,
            )
            .await;
            let mut validator = ObservingTableActivationValidator {
                tables: vec!["books".into()],
                calls: 0,
                seen: None,
            };
            let result = state
                .commit_validated_catalogue_table_request_activation(
                    ValidatedTableRequestActivationCommit {
                        writer,
                        identity,
                        fingerprint,
                        context: &context,
                        mutations: &mutations,
                        next_digest: digest(104),
                        outcome: outcome(105),
                        validator: &mut validator,
                        faults: &Fail(point),
                        effects: orna_evaluator::EffectGate::admit_unbound_for_test(),
                    },
                    &admission,
                )
                .await;
            assert!(
                matches!(result, Err(TableActivationError::Runtime(RuntimeError::FaultInjected(actual))) if actual == point)
            );
            assert_eq!(state.capture().await.unwrap(), *context.capture());
            assert_eq!(state.latest_checkpoint().await.unwrap(), None);
            assert!(state.pending().await.unwrap().is_empty());
            assert_eq!(
                state.committed_table_row("books", &[1]).await.unwrap(),
                None
            );
            assert_eq!(
                state.catalogue_function("pkg.activate").await.unwrap(),
                None
            );
            assert_eq!(
                state
                    .request_status(identity, fingerprint)
                    .await
                    .unwrap()
                    .unwrap()
                    .state,
                RequestState::Running
            );
            assert_eq!(
                state.run_observation(run.id).await.unwrap().unwrap().status,
                RunObservationStatus::Running
            );
        }
        let mut rejecting = RejectingValidator {
            tables: vec!["books".into()],
            calls: 0,
        };
        let rejected = state
            .commit_validated_catalogue_table_request_activation(
                ValidatedTableRequestActivationCommit {
                    writer,
                    identity,
                    fingerprint,
                    context: &context,
                    mutations: &mutations,
                    next_digest: digest(104),
                    outcome: outcome(105),
                    validator: &mut rejecting,
                    faults: &NoFault,
                    effects: orna_evaluator::EffectGate::admit_unbound_for_test(),
                },
                &admission,
            )
            .await;
        assert!(matches!(
            rejected,
            Err(TableActivationError::ValidationFailed(_))
        ));
        let mut validator = ObservingTableActivationValidator {
            tables: vec!["books".into()],
            calls: 0,
            seen: None,
        };
        for invalid_writer in [
            WriterLease {
                owner_id: id(5),
                epoch: writer.epoch,
            },
            WriterLease {
                owner_id: writer.owner_id,
                epoch: writer.epoch + 1,
            },
        ] {
            let result = state
                .commit_validated_catalogue_table_request_activation(
                    ValidatedTableRequestActivationCommit {
                        writer: invalid_writer,
                        identity,
                        fingerprint,
                        context: &context,
                        mutations: &mutations,
                        next_digest: digest(104),
                        outcome: outcome(105),
                        validator: &mut validator,
                        faults: &NoFault,
                        effects: orna_evaluator::EffectGate::admit_unbound_for_test(),
                    },
                    &admission,
                )
                .await;
            assert!(matches!(
                result,
                Err(TableActivationError::Runtime(RuntimeError::OwnerLost))
            ));
        }
        let invalid = activation_catalogue(None, 182);
        let result = state
            .commit_validated_catalogue_table_request_activation(
                ValidatedTableRequestActivationCommit {
                    writer,
                    identity,
                    fingerprint,
                    context: &context,
                    mutations: &mutations,
                    next_digest: digest(104),
                    outcome: outcome(105),
                    validator: &mut validator,
                    faults: &NoFault,
                    effects: orna_evaluator::EffectGate::admit_unbound_for_test(),
                },
                &invalid,
            )
            .await;
        assert!(matches!(
            result,
            Err(TableActivationError::Runtime(RuntimeError::RecoveryInvalid))
        ));
        let stale_context = RuntimeActivationContext {
            capture: CwdCapture::new(context.capture().snapshot().clone(), digest(200)).unwrap(),
            activation_time: context.activation_time(),
            table_object_ids: BTreeMap::new(),
            committed_rows: None,
        };
        let result = state
            .commit_validated_catalogue_table_request_activation(
                ValidatedTableRequestActivationCommit {
                    writer,
                    identity,
                    fingerprint,
                    context: &stale_context,
                    mutations: &mutations,
                    next_digest: digest(104),
                    outcome: outcome(105),
                    validator: &mut validator,
                    faults: &NoFault,
                    effects: orna_evaluator::EffectGate::admit_unbound_for_test(),
                },
                &admission,
            )
            .await;
        assert!(matches!(
            result,
            Err(TableActivationError::Runtime(
                RuntimeError::StaleCapture { .. }
            ))
        ));
        let (invalid_identity, invalid_fingerprint, _) =
            begin_continuable_request(&state, writer, 170, 171, 172).await;
        let mut invalid_batch = admission.clone();
        invalid_batch.functions[0].result_type_name = "pkg.Missing".into();
        let result = state
            .commit_validated_catalogue_table_request_activation(
                ValidatedTableRequestActivationCommit {
                    writer,
                    identity: invalid_identity,
                    fingerprint: invalid_fingerprint,
                    context: &context,
                    mutations: &mutations,
                    next_digest: digest(104),
                    outcome: outcome(105),
                    validator: &mut validator,
                    faults: &NoFault,
                    effects: orna_evaluator::EffectGate::admit_unbound_for_test(),
                },
                &invalid_batch,
            )
            .await;
        assert!(matches!(
            result,
            Err(TableActivationError::Runtime(RuntimeError::RecoveryInvalid))
        ));
        assert_eq!(validator.calls, 0);
        let mut identities = state
            .connection
            .query("SELECT COUNT(*) FROM runtime_catalogue_identity", ())
            .await
            .unwrap();
        assert_eq!(
            identities
                .next()
                .await
                .unwrap()
                .unwrap()
                .get::<i64>(0)
                .unwrap(),
            0
        );
        drop(identities);
        drop(state);
        let reopened = open_state(&repo).await;
        assert_eq!(reopened.capture().await.unwrap(), *context.capture());
        assert!(reopened.pending().await.unwrap().is_empty());
        assert_eq!(reopened.latest_checkpoint().await.unwrap(), None);
        assert_eq!(
            reopened.catalogue_function("pkg.activate").await.unwrap(),
            None
        );
        assert_eq!(
            reopened.committed_table_row("books", &[1]).await.unwrap(),
            None
        );
        assert_ne!(
            reopened
                .request_status(identity, fingerprint)
                .await
                .unwrap()
                .unwrap()
                .state,
            RequestState::Completed
        );
    }

    #[tokio::test]
    async fn activation_context_pins_capture_and_time_through_commit() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let lease = state.acquire_lease(id(4)).await.unwrap();
        let context = state.begin_activation().await.unwrap();
        let captured = context.capture().clone();
        let started = context.activation_time();

        let next = state
            .commit_activation(lease, &context, &[mutation(5)], digest(6), &NoFault)
            .await
            .unwrap();

        assert_eq!(context.capture(), &captured);
        assert_eq!(context.activation_time(), started);
        assert_ne!(next, captured);
        assert_eq!(state.capture().await.unwrap(), next);
    }

