    #[tokio::test]
    async fn explicit_rekey_is_atomic_and_retained_as_one_mutation() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let lease = state.acquire_lease(id(4)).await.unwrap();
        let context = state.begin_activation().await.unwrap();
        state
            .commit_table_activation(
                lease,
                &context,
                &[table_mutation(5, 1, Some(9)), table_mutation(6, 2, Some(8))],
                digest(7),
                &NoFault,
            )
            .await
            .unwrap();

        let context = state.begin_activation().await.unwrap();
        let duplicate_insert = TableMutation::insert(id(12), "books", vec![1], vec![11]).unwrap();
        let before = context.capture().clone();
        assert_eq!(
            state
                .commit_table_activation(
                    lease,
                    &context,
                    &[duplicate_insert],
                    digest(12),
                    &NoFault,
                )
                .await,
            Err(RuntimeError::InvalidTableMutation)
        );
        assert_eq!(state.capture().await.unwrap(), before);
        assert_eq!(
            state.committed_table_row("books", &[1]).await.unwrap(),
            Some(vec![9])
        );

        let insert = TableMutation::insert(id(13), "books", vec![3], vec![7]).unwrap();
        state
            .commit_table_activation(lease, &context, &[insert], digest(13), &NoFault)
            .await
            .unwrap();
        assert_eq!(
            state.committed_table_row("books", &[3]).await.unwrap(),
            Some(vec![7])
        );

        let context = state.begin_activation().await.unwrap();
        let occupied = TableMutation::rekey(id(8), "books", vec![1], vec![2], vec![10]).unwrap();
        let before = context.capture().clone();
        assert_eq!(
            state
                .commit_table_activation(lease, &context, &[occupied], digest(9), &NoFault)
                .await,
            Err(RuntimeError::InvalidTableMutation)
        );
        assert_eq!(state.capture().await.unwrap(), before);
        assert_eq!(
            state.committed_table_row("books", &[1]).await.unwrap(),
            Some(vec![9])
        );
        assert_eq!(
            state.committed_table_row("books", &[2]).await.unwrap(),
            Some(vec![8])
        );

        let rekey = TableMutation::rekey(id(10), "books", vec![1], vec![4], vec![10]).unwrap();
        state
            .commit_table_activation(lease, &context, &[rekey], digest(11), &NoFault)
            .await
            .unwrap();
        assert_eq!(
            state.committed_table_row("books", &[1]).await.unwrap(),
            None
        );
        assert_eq!(
            state.committed_table_row("books", &[4]).await.unwrap(),
            Some(vec![10])
        );

        let pending = state.pending().await.unwrap();
        let retained = TableMutation::decode(pending.last().unwrap()).unwrap();
        assert_eq!(retained.key(), &[1]);
        assert_eq!(retained.rekey_to(), Some(&[4][..]));
        assert!(
            pending
                .last()
                .unwrap()
                .payload
                .starts_with(b"ORNA-TABLE-MUTATION-2\0")
        );
    }

    #[tokio::test]
    async fn typed_table_activation_records_a_missing_delete_as_an_advancing_no_op() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let lease = state.acquire_lease(id(4)).await.unwrap();
        let context = state.begin_activation().await.unwrap();
        state
            .commit_table_activation(
                lease,
                &context,
                &[table_mutation(9, 1, None)],
                digest(10),
                &NoFault,
            )
            .await
            .unwrap();
        assert!(state.latest_checkpoint().await.unwrap().is_some());
        assert_eq!(state.pending().await.unwrap().len(), 1);
        assert_eq!(
            state.committed_table_row("books", &[1]).await.unwrap(),
            None
        );
        // The no-op delete still advances history as a deleted row with no
        // value, so `as_of` reads see the same absence as the live relation.
        let mut history = state
            .connection
            .query(
                "SELECT row_value IS NULL, deleted FROM runtime_table_history
                 WHERE table_id = 'books' AND row_key = ?1",
                params![vec![1_u8]],
            )
            .await
            .unwrap();
        let row = history.next().await.unwrap().unwrap();
        assert_eq!(row.get::<i64>(0).unwrap(), 1);
        assert_eq!(row.get::<i64>(1).unwrap(), 1);
        assert!(history.next().await.unwrap().is_none());
    }

    #[tokio::test]
    async fn partially_retained_table_batch_is_rejected_without_publishing() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let lease = state.acquire_lease(id(4)).await.unwrap();
        let cwd_generation = activation_test_cwd_generation(0);
        let context = state.begin_activation().await.unwrap();
        let mut validator = ObservingTableActivationValidator {
            tables: vec!["books".into()],
            calls: 0,
            seen: None,
        };
        state
            .commit_validated_table_activation(ValidatedTableActivationCommit {
                writer: lease,
                context: &context,
                cwd_generation: Some(cwd_generation),
                expected_schema: None,
                mutations: &[table_mutation(20, 1, Some(9))],
                content_pins: &mut [],
                next_digest: digest(6),
                validator: &mut validator,
                faults: &NoFault,
            })
            .await
            .unwrap();
        let capture_before = state.capture().await.unwrap();
        let checkpoint_before = state.latest_checkpoint().await.unwrap();
        assert_eq!(state.pending().await.unwrap().len(), 1);

        // Mutation 20 is already retained, so replaying it beside new mutation
        // 21 reuses an identity for only part of the batch: that is invalid.
        let context = state.begin_activation().await.unwrap();
        let mut validator = ObservingTableActivationValidator {
            tables: vec!["books".into()],
            calls: 0,
            seen: None,
        };
        let partial = state
            .commit_validated_table_activation(ValidatedTableActivationCommit {
                writer: lease,
                context: &context,
                cwd_generation: Some(cwd_generation),
                expected_schema: None,
                mutations: &[
                    table_mutation(20, 1, Some(9)),
                    table_mutation(21, 2, Some(8)),
                ],
                content_pins: &mut [],
                next_digest: digest(7),
                validator: &mut validator,
                faults: &NoFault,
            })
            .await;
        assert!(matches!(
            partial,
            Err(TableActivationError::Runtime(
                RuntimeError::InvalidTableMutation
            ))
        ));
        assert_eq!(validator.calls, 0);
        assert_eq!(state.capture().await.unwrap(), capture_before);
        assert_eq!(state.latest_checkpoint().await.unwrap(), checkpoint_before);
        assert_eq!(state.pending().await.unwrap().len(), 1);
        assert_eq!(
            state.committed_table_row("books", &[1]).await.unwrap(),
            Some(vec![9])
        );
        assert_eq!(
            state.committed_table_row("books", &[2]).await.unwrap(),
            None
        );
    }

