    #[tokio::test]
    async fn accepted_pin_checkpoint_recovers_committed_state_and_discards_interrupted_state() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let lease = state.acquire_lease(id(4)).await.unwrap();
        let context = state.begin_activation().await.unwrap();
        let cwd_generation = activation_test_cwd_generation(0);
        let mut validator = ObservingTableActivationValidator {
            tables: vec!["books".into()],
            calls: 0,
            seen: None,
        };
        state
            .commit_validated_table_activation(ValidatedTableActivationCommit {
                writer: lease,
                context: &context,
                cwd_generation: Some(cwd_generation),
                expected_schema: None,
                mutations: &[table_mutation(5, 1, Some(9))],
                content_pins: &mut [],
                next_digest: digest(6),
                validator: &mut validator,
                faults: &NoFault,
            })
            .await
            .unwrap();
        drop(state);

        let reopened = open_state(&repo).await;
        assert_eq!(
            reopened.committed_table_row("books", &[1]).await.unwrap(),
            Some(vec![9])
        );
        assert_eq!(
            reopened
                .latest_checkpoint()
                .await
                .unwrap()
                .unwrap()
                .generation,
            1
        );

        // Model a process interruption after the candidate row, checkpoint,
        // and transfer metadata have been written but before COMMIT. This is
        // SQL transaction fault injection, not a pin issuer or transfer proof.
        let interrupted_context = reopened.begin_activation().await.unwrap();
        let interrupted_mutation = table_mutation(7, 2, Some(8));
        let encoded = interrupted_mutation.runtime_mutation().unwrap();
        let transaction = reopened
            .connection
            .transaction_with_behavior(TransactionBehavior::Immediate)
            .await
            .unwrap();
        let mut base = CommittedTableBase::default();
        apply_table_mutation_tx(&transaction, &interrupted_mutation, &mut base)
            .await
            .unwrap();
        let interrupted_capture = append_mutations_tx(
            &transaction,
            interrupted_context.capture(),
            &[encoded],
            digest(8),
            &NoFault,
        )
        .await
        .unwrap();
        let interrupted_generation = i64::try_from(
            interrupted_capture
                .generation()
                .to_u64_digits()
                .1
                .first()
                .copied()
                .unwrap_or(0),
        )
        .unwrap();
        transaction
            .execute(
                "INSERT INTO accepted_content_pin
                 (pin_id, repository_id, database_id, descriptor_oid_algorithm,
                  descriptor_oid, content_length, content_sha256, owner_id,
                  owner_epoch, checkpoint_generation)
                 VALUES (?1, ?2, ?3, 1, ?4, 0, ?5, ?6, 1, ?7)",
                params![
                    id(88).to_vec(),
                    vec![0x88; 32],
                    id(1).to_vec(),
                    vec![0; 20],
                    vec![0; 32],
                    id(7).to_vec(),
                    interrupted_generation,
                ],
            )
            .await
            .unwrap();
        drop(transaction);
        drop(reopened);

        let recovered = open_state(&repo).await;
        assert_eq!(
            recovered.committed_table_row("books", &[1]).await.unwrap(),
            Some(vec![9])
        );
        assert_eq!(
            recovered.committed_table_row("books", &[2]).await.unwrap(),
            None
        );
        assert_eq!(
            recovered
                .latest_checkpoint()
                .await
                .unwrap()
                .unwrap()
                .generation,
            1
        );
        let mut pins = recovered
            .connection
            .query("SELECT COUNT(*) FROM accepted_content_pin", ())
            .await
            .unwrap();
        assert_eq!(
            pins.next().await.unwrap().unwrap().get::<i64>(0).unwrap(),
            0
        );
    }

    #[tokio::test]
    async fn accepted_content_pins_for_descriptor_lists_only_matching_pins() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let graph_repository_id = state
            .graph_repository_id
            .expect("a repository-opened runtime carries its graph repository id");
        let descriptor = NativeOid::new(GitHashAlgorithm::Sha1, vec![0x44; 20]).unwrap();
        let other_descriptor = NativeOid::new(GitHashAlgorithm::Sha1, vec![0x45; 20]).unwrap();
        // Pin metadata is injected directly: this exercises the lookup over
        // persisted rows, not a pin issuer or transfer proof.
        for (pin, repository, oid, length) in [
            (88, graph_repository_id, &descriptor, 5_i64),
            (89, graph_repository_id, &descriptor, 6_i64),
            (90, [0x99; 32], &descriptor, 7_i64),
            (91, graph_repository_id, &other_descriptor, 8_i64),
        ] {
            state
                .connection
                .execute(
                    "INSERT INTO accepted_content_pin
                     (pin_id, repository_id, database_id, descriptor_oid_algorithm,
                      descriptor_oid, content_length, content_sha256, owner_id,
                      owner_epoch, checkpoint_generation)
                     VALUES (?1, ?2, ?3, 1, ?4, ?5, ?6, ?7, 1, NULL)",
                    params![
                        id(pin).to_vec(),
                        repository.to_vec(),
                        id(1).to_vec(),
                        oid.as_bytes().to_vec(),
                        length,
                        vec![pin; 32],
                        id(7).to_vec(),
                    ],
                )
                .await
                .unwrap();
        }

        let pins = state
            .accepted_content_pins_for_descriptor(&descriptor)
            .await
            .unwrap();
        let listed = pins
            .iter()
            .map(|pin| (*pin.pin_id(), pin.content_length(), *pin.content_sha256()))
            .collect::<Vec<_>>();
        assert_eq!(
            listed,
            vec![(id(88), 5, [88; 32]), (id(89), 6, [89; 32])],
            "wrong repository (pin 90) and wrong descriptor (pin 91) are excluded"
        );

        let other = state
            .accepted_content_pins_for_descriptor(&other_descriptor)
            .await
            .unwrap();
        assert_eq!(other.len(), 1);
        assert_eq!(other[0].pin_id(), &id(91));

        let absent = NativeOid::new(GitHashAlgorithm::Sha1, vec![0x46; 20]).unwrap();
        assert!(
            state
                .accepted_content_pins_for_descriptor(&absent)
                .await
                .unwrap()
                .is_empty()
        );
    }

