    #[tokio::test]
    async fn query_take_two_respects_child_leaf_cap_before_outer_union_demand() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let lease = state.acquire_lease(id(4)).await.unwrap();
        let context = state.begin_activation().await.unwrap();
        let mutations = (7u8..=9)
            .map(|row_id| {
                let target = if row_id == 9 { 99 } else { row_id };
                query_test_mutation(
                    row_id + 40,
                    row_id,
                    Some(query_test_row(row_id, "current", target)),
                )
            })
            .collect::<Vec<_>>();
        state
            .commit_table_activation(lease, &context, &mutations, digest(125), &NoFault)
            .await
            .unwrap();

        let snapshot = state
            .begin_table_activation(&["sys.Storage"])
            .await
            .unwrap();
        let session = snapshot.query_session();

        // The reference requires take to avoid enumeration beyond the
        // demanded result, but leaves an effectful child cap implicit. When
        // both take(2) limits end together, the third left row's bad lookup
        // and the right sibling must remain unevaluated.
        let (at_child_cap, lookups, scans) = invoke_query_fixture_with_counts(
            &session,
            include_str!(
                "../tests/fixtures/query-session-union-project-left-take-two-exact-outer-bound.orna"
            ),
        );
        assert_eq!(
            at_child_cap.unwrap(),
            CanonicalValue::new(OvbRaw::Int(BigInt::from(2u8))).unwrap()
        );
        assert_eq!(
            (lookups, scans),
            (2, 2),
            "the equal child and outer take(2) bounds leave the failing third left row unopened"
        );

        // If the outer demand continues past the left child cap, the child
        // ends cleanly and union advances to one right-side row without
        // projecting the excluded third left row.
        let (past_child_cap, lookups, scans) = invoke_query_fixture_with_counts(
            &session,
            include_str!(
                "../tests/fixtures/query-session-union-project-left-take-two-outer-crosses-cap.orna"
            ),
        );
        assert_eq!(
            past_child_cap.unwrap(),
            CanonicalValue::new(OvbRaw::Int(BigInt::from(3u8))).unwrap()
        );
        assert_eq!(
            (lookups, scans),
            (3, 3),
            "outer demand past the child cap visits one right row and leaves the excluded failure latent"
        );
    }

