    fn stream_delivery(position: &str, successor: &str) -> DeliveryIdentity {
        DeliveryIdentity {
            consumer: ConsumerIdentity {
                principal: Component::new("principal").unwrap(),
                root: Component::new("root").unwrap(),
                function: Component::new("consume").unwrap(),
                binding: Component::new("binding").unwrap(),
            },
            source_format: Component::new("source-format").unwrap(),
            source: Component::new("source").unwrap(),
            partition_format: Component::new("partition-format").unwrap(),
            partition: Some(Component::new("partition").unwrap()),
            position_format: Component::new("position-format").unwrap(),
            position: Position {
                token: Component::new(position).unwrap(),
            },
            successor: Position {
                token: Component::new(successor).unwrap(),
            },
        }
    }

    #[tokio::test]
    async fn checkpoint_history_retains_complete_and_skip_by_snapshot() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(90)).await.unwrap();
        let complete = stream_delivery("history-complete", "history-complete-next");
        let key = complete.checkpoint_key();
        let initial = CheckpointPrecondition {
            version: 0,
            committed: None,
        };
        let capture_before = state.capture().await.unwrap();
        let complete_lease = {
            let mut stream = state.stream_backend(writer);
            match stream
                .apply_async(CommitIntent::Acquire {
                    delivery: complete,
                    expected: initial.clone(),
                    purpose: LeasePurpose::Deliver,
                })
                .await
                .unwrap()
            {
                CommitResult::Acquired { lease } => lease,
                other => panic!("unexpected completion lease: {other:?}"),
            }
        };
        let (capture_after_complete, result) = state
            .commit_stream_delivery(StreamDeliveryCommit {
                writer,
                expected_capture: &capture_before,
                mutations: &[],
                next_digest: capture_before.generation_digest(),
                delivery: complete_lease,
                expected_stream: initial,
                faults: &NoFault,
            })
            .await
            .unwrap();
        assert!(matches!(
            result,
            CommitResult::CheckpointAdvanced {
                checkpoint: StreamCheckpoint { version: 1, .. }
            }
        ));
        let first = state
            .stream_checkpoint_history_at(&key, &capture_after_complete)
            .await
            .unwrap();
        assert_eq!(first.len(), 1);
        assert_eq!(first[0].checkpoint.version, 1);
        assert_eq!(
            first[0]
                .checkpoint
                .committed
                .as_ref()
                .unwrap()
                .token
                .as_str(),
            "history-complete-next"
        );
        assert_eq!(first[0].transition, StreamCheckpointTransition::Complete);

        let capture_after_table = state
            .commit(
                writer,
                &capture_after_complete,
                &mutation(90),
                digest(91),
                &NoFault,
            )
            .await
            .unwrap();
        let checkpoint = state.stream_checkpoint(&key).await.unwrap();
        let skip = stream_delivery("history-skip", "history-skip-next");
        let failed = {
            let mut stream = state.stream_backend(writer);
            let lease = match stream
                .apply_async(CommitIntent::Acquire {
                    delivery: skip.clone(),
                    expected: CheckpointPrecondition::from(&checkpoint),
                    purpose: LeasePurpose::Deliver,
                })
                .await
                .unwrap()
            {
                CommitResult::Acquired { lease } => lease,
                other => panic!("unexpected failure lease: {other:?}"),
            };
            match stream
                .fail_with_payload_async(
                    lease,
                    SafeDiagnostic {
                        code: DiagnosticCode::ExecutionRejected,
                        class: DiagnosticClass::Permanent,
                    },
                    StreamFailurePayload::Plaintext(vec![1, 2, 3]),
                )
                .await
                .unwrap()
            {
                CommitResult::Failed { failure } => failure,
                other => panic!("unexpected failure result: {other:?}"),
            }
        };
        let after_failure = state
            .stream_checkpoint_history_at(&key, &capture_after_table)
            .await
            .unwrap();
        assert_eq!(after_failure, first);
        {
            let mut stream = state.stream_backend(writer);
            let skip_lease = match stream
                .apply_async(CommitIntent::Acquire {
                    delivery: skip,
                    expected: CheckpointPrecondition::from(&checkpoint),
                    purpose: LeasePurpose::Skip,
                })
                .await
                .unwrap()
            {
                CommitResult::Acquired { lease } => lease,
                other => panic!("unexpected skip lease: {other:?}"),
            };
            assert!(matches!(
                stream
                    .apply_async(CommitIntent::Skip {
                        lease: skip_lease,
                        expected: CheckpointPrecondition::from(&checkpoint),
                        expected_failure_version: failed.version,
                    })
                    .await
                    .unwrap(),
                CommitResult::CheckpointAdvanced {
                    checkpoint: StreamCheckpoint { version: 2, .. }
                }
            ));
        }
        let current = state.capture().await.unwrap();
        let selected_first = state
            .stream_checkpoint_history_at(&key, &capture_after_complete)
            .await
            .unwrap();
        assert_eq!(selected_first.len(), 1);
        let selected_current = state
            .stream_checkpoint_history_at(&key, &current)
            .await
            .unwrap();
        assert_eq!(selected_current.len(), 2);
        assert_eq!(
            selected_current[1].transition,
            StreamCheckpointTransition::Skip
        );
        assert_eq!(
            selected_current[1]
                .checkpoint
                .committed
                .as_ref()
                .unwrap()
                .token
                .as_str(),
            "history-skip-next"
        );
        assert_eq!(current, capture_after_table);
        state.validate_recovery().await.unwrap();
        let key_id = stream_key_id(&key);
        let committed = selected_current[0]
            .checkpoint
            .committed
            .as_ref()
            .unwrap()
            .token
            .as_str()
            .to_owned();
        let snapshot = encode_capture(&selected_current[0].capture).unwrap();
        let generation_digest = selected_current[0].capture.generation_digest().to_vec();
        state
            .connection
            .execute(
                "DELETE FROM stream_checkpoint_history WHERE key_id = ?1 AND version = 1",
                params![key_id.clone()],
            )
            .await
            .unwrap();
        assert_eq!(
            state.validate_recovery().await,
            Err(RuntimeError::RecoveryInvalid)
        );
        state
            .connection
            .execute(
                "INSERT INTO stream_checkpoint_history
                 (key_id, version, committed_position, snapshot, generation_digest, transition)
                 VALUES (?1, 1, ?2, ?3, ?4, 1)",
                params![
                    key_id.clone(),
                    committed.clone(),
                    snapshot.clone(),
                    generation_digest.clone()
                ],
            )
            .await
            .unwrap();
        state
            .connection
            .execute(
                "UPDATE stream_checkpoint_history SET version = 3
                 WHERE key_id = ?1 AND version = 1",
                params![key_id.clone()],
            )
            .await
            .unwrap();
        assert_eq!(
            state.validate_recovery().await,
            Err(RuntimeError::RecoveryInvalid)
        );
        state
            .connection
            .execute(
                "UPDATE stream_checkpoint_history SET version = 1
                 WHERE key_id = ?1 AND version = 3",
                params![key_id.clone()],
            )
            .await
            .unwrap();
        state
            .connection
            .execute(
                "UPDATE stream_checkpoint_history SET version = 4
                 WHERE key_id = ?1 AND version = 2",
                params![key_id.clone()],
            )
            .await
            .unwrap();
        assert_eq!(
            state.validate_recovery().await,
            Err(RuntimeError::RecoveryInvalid)
        );
        state
            .connection
            .execute(
                "UPDATE stream_checkpoint_history SET version = 2
                 WHERE key_id = ?1 AND version = 4",
                params![key_id.clone()],
            )
            .await
            .unwrap();
        state
            .connection
            .execute(
                "UPDATE stream_checkpoint_history SET snapshot = ?2
                 WHERE key_id = ?1 AND version = 1",
                params![key_id.clone(), vec![1_u8, 2, 3]],
            )
            .await
            .unwrap();
        assert_eq!(
            state.validate_recovery().await,
            Err(RuntimeError::RecoveryInvalid)
        );
        state
            .connection
            .execute(
                "UPDATE stream_checkpoint_history SET snapshot = ?2
                 WHERE key_id = ?1 AND version = 1",
                params![key_id, snapshot],
            )
            .await
            .unwrap();
        state.validate_recovery().await.unwrap();
        assert_eq!(current, capture_after_table);
        drop(state);

        let reopened = open_state(&repo).await;
        let reopened_history = reopened
            .stream_checkpoint_history_at(&key, &current)
            .await
            .unwrap();
        assert_eq!(reopened_history, selected_current);
    }

    fn assertion_detail(snapshot: Snapshot) -> AssertionDiagnosticDetail {
        let reference = |key: &str| {
            RowRef::new(id(1), id(9), OvbRaw::Text(key.into()), snapshot.clone()).unwrap()
        };
        let file = orna_foundation::FileRef::from_row_ref(reference("file"));
        AssertionDiagnosticDetail::table_or_cross_table_false(
            AssertionRef::from_row_ref(reference("assertion")),
            ObjectRef::from_row_ref(reference("owner")),
            AssertionOwnerKind::Table,
            ExpressionRef::from_row_ref(reference("predicate")),
            SourceSpan::new(
                file,
                4.into(),
                9.into(),
                1.into(),
                5.into(),
                1.into(),
                10.into(),
            )
            .unwrap(),
            Some(SafeAssertionWitness::from_safe_presentation(
                SafeText::new("stable-safe-witness").unwrap(),
            )),
        )
    }

    #[tokio::test]
    async fn assertion_failure_detail_survives_retry_and_reopen() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(24)).await.unwrap();
        let delivery = stream_delivery("assertion-detail", "after-assertion-detail");
        let expected = CheckpointPrecondition {
            version: 0,
            committed: None,
        };
        let detail = assertion_detail(state.capture().await.unwrap().snapshot().clone());
        let failed = {
            let mut stream = state.stream_backend(writer);
            let lease = match stream
                .apply_async(CommitIntent::Acquire {
                    delivery: delivery.clone(),
                    expected: expected.clone(),
                    purpose: LeasePurpose::Deliver,
                })
                .await
                .unwrap()
            {
                CommitResult::Acquired { lease } => lease,
                other => panic!("unexpected acquire result: {other:?}"),
            };
            match stream
                .fail_with_assertion_detail_async(
                    lease,
                    SafeDiagnostic {
                        code: DiagnosticCode::ExecutionRejected,
                        class: DiagnosticClass::Permanent,
                    },
                    detail.clone(),
                    StreamFailurePayload::Plaintext(vec![7]),
                )
                .await
                .unwrap()
            {
                CommitResult::Failed { failure } => failure,
                other => panic!("unexpected failure result: {other:?}"),
            }
        };
        assert_eq!(failed.assertion_detail, Some(detail.clone()));
        {
            let mut stream = state.stream_backend(writer);
            assert!(matches!(
                stream
                    .apply_async(CommitIntent::Retry {
                        failure: failed.identity.clone(),
                        expected_version: failed.version,
                        expected,
                    })
                    .await
                    .unwrap(),
                CommitResult::RetryScheduled { ref failure }
                    if failure.assertion_detail == Some(detail.clone())
            ));
        }
        drop(state);
        let reopened = open_state(&repo).await;
        let stream = reopened.stream_backend(writer);
        let loaded = stream
            .failure_async(&failed.identity)
            .await
            .unwrap()
            .expect("durable assertion failure");
        assert_eq!(loaded.assertion_detail, Some(detail));
        assert_eq!(loaded.attempts, 2);
    }

    #[tokio::test]
    async fn assertion_replay_failure_preserves_identity_and_detail_until_ordinary_failure() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(25)).await.unwrap();
        let delivery = stream_delivery("replay-assertion", "after-replay-assertion");
        let initial = CheckpointPrecondition {
            version: 0,
            committed: None,
        };
        let detail = assertion_detail(state.capture().await.unwrap().snapshot().clone());
        let failed = {
            let mut stream = state.stream_backend(writer);
            let lease = match stream
                .apply_async(CommitIntent::Acquire {
                    delivery: delivery.clone(),
                    expected: initial.clone(),
                    purpose: LeasePurpose::Deliver,
                })
                .await
                .unwrap()
            {
                CommitResult::Acquired { lease } => lease,
                other => panic!("unexpected acquire result: {other:?}"),
            };
            match stream
                .fail_with_assertion_detail_async(
                    lease,
                    SafeDiagnostic {
                        code: DiagnosticCode::ExecutionRejected,
                        class: DiagnosticClass::Permanent,
                    },
                    detail.clone(),
                    StreamFailurePayload::Plaintext(vec![8]),
                )
                .await
                .unwrap()
            {
                CommitResult::Failed { failure } => failure,
                other => panic!("unexpected failure result: {other:?}"),
            }
        };
        let (skipped, checkpoint_before_replay) = {
            let mut stream = state.stream_backend(writer);
            let skip_lease = match stream
                .apply_async(CommitIntent::Acquire {
                    delivery: delivery.clone(),
                    expected: initial.clone(),
                    purpose: LeasePurpose::Skip,
                })
                .await
                .unwrap()
            {
                CommitResult::Acquired { lease } => lease,
                other => panic!("unexpected skip lease: {other:?}"),
            };
            assert!(matches!(
                stream
                    .apply_async(CommitIntent::Skip {
                        lease: skip_lease,
                        expected: initial,
                        expected_failure_version: failed.version,
                    })
                    .await
                    .unwrap(),
                CommitResult::CheckpointAdvanced { .. }
            ));
            let skipped = stream
                .failure_async(&failed.identity)
                .await
                .unwrap()
                .expect("skipped failure");
            let checkpoint = stream
                .checkpoint_async(&delivery.checkpoint_key())
                .await
                .unwrap();
            (skipped, checkpoint)
        };
        let replay_failed = {
            let mut stream = state.stream_backend(writer);
            let grant = match stream
                .apply_async(CommitIntent::Replay {
                    failure: skipped.identity.clone(),
                    expected_version: skipped.version,
                })
                .await
                .unwrap()
            {
                CommitResult::ReplayGranted { grant } => grant,
                other => panic!("unexpected replay grant: {other:?}"),
            };
            match stream
                .apply_async(CommitIntent::ReplayFailWithAssertion {
                    failure: grant.failure,
                    expected_version: grant.version,
                    diagnostic: SafeDiagnostic {
                        code: DiagnosticCode::DecodeRejected,
                        class: DiagnosticClass::Permanent,
                    },
                    detail: detail.clone(),
                })
                .await
                .unwrap()
            {
                CommitResult::ReplayFailed { failure } => failure,
                other => panic!("unexpected replay failure result: {other:?}"),
            }
        };
        assert_eq!(replay_failed.identity, failed.identity);
        assert_eq!(
            replay_failed.diagnostic.code,
            DiagnosticCode::TableAssertionFalse
        );
        assert_eq!(replay_failed.assertion_detail, Some(detail.clone()));
        let stream = state.stream_backend(writer);
        assert_eq!(
            stream
                .checkpoint_async(&delivery.checkpoint_key())
                .await
                .unwrap(),
            checkpoint_before_replay
        );
        drop(state);

        let reopened = open_state(&repo).await;
        let mut stream = reopened.stream_backend(writer);
        let loaded = stream
            .failure_async(&failed.identity)
            .await
            .unwrap()
            .expect("replayed assertion failure");
        assert_eq!(loaded.identity, failed.identity);
        assert_eq!(loaded.assertion_detail, Some(detail));
        let grant = match stream
            .apply_async(CommitIntent::Replay {
                failure: loaded.identity.clone(),
                expected_version: loaded.version,
            })
            .await
            .unwrap()
        {
            CommitResult::ReplayGranted { grant } => grant,
            other => panic!("unexpected second replay grant: {other:?}"),
        };
        let ordinary = match stream
            .apply_async(CommitIntent::ReplayFail {
                failure: grant.failure,
                expected_version: grant.version,
                diagnostic: SafeDiagnostic {
                    code: DiagnosticCode::ExecutionRejected,
                    class: DiagnosticClass::Permanent,
                },
            })
            .await
            .unwrap()
        {
            CommitResult::ReplayFailed { failure } => failure,
            other => panic!("unexpected ordinary replay failure result: {other:?}"),
        };
        assert_eq!(ordinary.identity, failed.identity);
        assert_eq!(ordinary.assertion_detail, None);
        assert_eq!(
            stream
                .checkpoint_async(&delivery.checkpoint_key())
                .await
                .unwrap(),
            checkpoint_before_replay
        );
    }

