    #[tokio::test]
    async fn direct_failure_recovery_rejects_corrupt_identity_or_checkpoint_key() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(27)).await.unwrap();
        let delivery = stream_delivery("failure-integrity", "failure-integrity-next");
        let expected = CheckpointPrecondition {
            version: 0,
            committed: None,
        };
        let failure = {
            let mut stream = state.stream_backend(writer);
            let lease = match stream
                .apply_async(CommitIntent::Acquire {
                    delivery: delivery.clone(),
                    expected: expected.clone(),
                    purpose: LeasePurpose::Deliver,
                })
                .await
                .unwrap()
            {
                CommitResult::Acquired { lease } => lease,
                other => panic!("unexpected acquire result: {other:?}"),
            };
            match stream
                .fail_async(
                    lease,
                    SafeDiagnostic {
                        code: DiagnosticCode::ExecutionRejected,
                        class: DiagnosticClass::Permanent,
                    },
                    StreamFailurePayload::Plaintext(vec![27]),
                )
                .await
                .unwrap()
            {
                CommitResult::Failed { failure } => failure,
                other => panic!("unexpected failure result: {other:?}"),
            }
        };
        let key = delivery.checkpoint_key();
        let identity_id = stream_identity_id(&failure.identity);
        let key_id = stream_key_id(&key);
        let checkpoint_before = load_stream_checkpoint_state(&state.connection, &key)
            .await
            .unwrap();

        let after_stale_retries = state
            .stream_backend(writer)
            .failure_async(&failure.identity)
            .await
            .unwrap()
            .expect("stale retries must retain the failure record");
        assert_eq!(after_stale_retries, failure);
        assert!(
            load_stream_lease(&state.connection, &key)
                .await
                .unwrap()
                .is_none(),
            "stale retries must not create a delivery lease"
        );

        state
            .connection
            .execute(
                "UPDATE stream_failure SET key_id = 'corrupt-checkpoint-key'
                 WHERE identity_id = ?1",
                params![identity_id.clone()],
            )
            .await
            .unwrap();
        assert_eq!(
            state
                .stream_backend(writer)
                .failure_async(&failure.identity)
                .await,
            Err(RuntimeError::RecoveryInvalid)
        );
        assert_eq!(
            state
                .stream_backend(writer)
                .apply_async(CommitIntent::Retry {
                    failure: failure.identity.clone(),
                    expected_version: failure.version,
                    expected: expected.clone(),
                })
                .await,
            Err(RuntimeError::RecoveryInvalid)
        );
        assert_eq!(
            load_stream_checkpoint_state(&state.connection, &key)
                .await
                .unwrap(),
            checkpoint_before
        );

        state
            .connection
            .execute(
                "UPDATE stream_failure SET key_id = ?2 WHERE identity_id = ?1",
                params![identity_id.clone(), key_id],
            )
            .await
            .unwrap();
        let mut corrupt_identity = failure.identity.clone();
        corrupt_identity.0.position = Position {
            token: Component::new("corrupt-position").unwrap(),
        };
        let corrupt_identity_id = stream_identity_id(&corrupt_identity);
        state
            .connection
            .execute(
                "UPDATE stream_failure SET identity_id = ?2 WHERE identity_id = ?1",
                params![identity_id.clone(), corrupt_identity_id.clone()],
            )
            .await
            .unwrap();
        assert_eq!(
            state
                .stream_backend(writer)
                .failure_async(&corrupt_identity)
                .await,
            Err(RuntimeError::RecoveryInvalid)
        );
        assert_eq!(
            state
                .stream_backend(writer)
                .apply_async(CommitIntent::Retry {
                    failure: corrupt_identity,
                    expected_version: failure.version,
                    expected,
                })
                .await,
            Err(RuntimeError::RecoveryInvalid)
        );
        assert_eq!(
            load_stream_checkpoint_state(&state.connection, &key)
                .await
                .unwrap(),
            checkpoint_before
        );

        state
            .connection
            .execute(
                "UPDATE stream_failure SET identity_id = ?2 WHERE identity_id = ?1",
                params![corrupt_identity_id, identity_id],
            )
            .await
            .unwrap();
    }

    #[tokio::test]
    async fn failure_reference_resolution_is_exact_and_fails_closed() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(28)).await.unwrap();
        let capture = state.capture().await.unwrap();
        state
            .admit_catalogue_at(writer, &capture, activation_catalogue(None, 28))
            .await
            .unwrap();
        let delivery = stream_delivery("resolve-reference", "resolve-successor");
        let expected = CheckpointPrecondition {
            version: 0,
            committed: None,
        };
        let failure = {
            let mut stream = state.stream_backend(writer);
            let lease = match stream
                .apply_async(CommitIntent::Acquire {
                    delivery: delivery.clone(),
                    expected,
                    purpose: LeasePurpose::Deliver,
                })
                .await
                .unwrap()
            {
                CommitResult::Acquired { lease } => lease,
                other => panic!("unexpected acquire result: {other:?}"),
            };
            match stream
                .fail_async(
                    lease,
                    SafeDiagnostic {
                        code: DiagnosticCode::ExecutionRejected,
                        class: DiagnosticClass::Permanent,
                    },
                    StreamFailurePayload::Plaintext(vec![28]),
                )
                .await
                .unwrap()
            {
                CommitResult::Failed { failure } => failure,
                other => panic!("unexpected failure result: {other:?}"),
            }
        };
        let reference = failure_reference(
            capture.database_id(),
            capture.snapshot().clone(),
            failure.identity.0.consumer.canonical(),
            failure.identity.0.source.as_str().to_owned(),
            failure
                .identity
                .0
                .partition
                .as_ref()
                .map(|value| value.as_str().to_owned()),
            failure.identity.0.position_format.as_str().to_owned(),
            failure.identity.0.position.token.as_str().to_owned(),
        )
        .unwrap();

        state
            .connection
            .execute("UPDATE runtime_meta SET generation = generation + 1", ())
            .await
            .unwrap();
        assert_ne!(
            state.capture().await.unwrap().snapshot(),
            capture.snapshot()
        );
        assert_eq!(
            state.resolve_failure_reference(&reference).await.unwrap(),
            Some(failure.clone())
        );

        let absent = failure_reference(
            capture.database_id(),
            capture.snapshot().clone(),
            failure.identity.0.consumer.canonical(),
            failure.identity.0.source.as_str().to_owned(),
            failure
                .identity
                .0
                .partition
                .as_ref()
                .map(|value| value.as_str().to_owned()),
            failure.identity.0.position_format.as_str().to_owned(),
            "not-retained".into(),
        )
        .unwrap();
        assert_eq!(
            state.resolve_failure_reference(&absent).await.unwrap(),
            None
        );

        let alternate = FailureIdentity(DeliveryIdentity {
            source_format: Component::new("alternate-source-format").unwrap(),
            ..failure.identity.0.clone()
        });
        state
            .connection
            .execute(
                "INSERT INTO stream_failure (
                    identity_id, key_id, consumer_principal, consumer_root,
                    consumer_function, consumer_binding, source_format, source,
                    partition_format, partition, position_format,
                    delivery_position, successor_position, version, attempts,
                    status, diagnostic_code, diagnostic_class
                 )
                 SELECT ?1, ?2, consumer_principal, consumer_root,
                        consumer_function, consumer_binding, ?3, source,
                        partition_format, partition, position_format,
                        delivery_position, successor_position, version, attempts,
                        status, diagnostic_code, diagnostic_class
                 FROM stream_failure WHERE identity_id = ?4",
                params![
                    stream_identity_id(&alternate),
                    stream_key_id(&alternate.0.checkpoint_key()),
                    alternate.0.source_format.as_str().to_owned(),
                    stream_identity_id(&failure.identity),
                ],
            )
            .await
            .unwrap();
        assert_eq!(
            state.resolve_failure_reference(&reference).await,
            Err(RuntimeError::RecoveryInvalid)
        );
    }

