    async fn protected_replay_fixture(
        state: &RuntimeState,
        writer: WriterLease,
        label: &str,
        payload_digest: [u8; 32],
    ) -> (ReplayGrant, StreamCheckpoint, DeliveryIdentity) {
        let delivery = stream_delivery(label, &format!("{label}-next"));
        let expected = CheckpointPrecondition {
            version: 0,
            committed: None,
        };
        let mut stream = state.stream_backend(writer);
        let lease = match stream
            .apply_async(CommitIntent::Acquire {
                delivery: delivery.clone(),
                expected: expected.clone(),
                purpose: LeasePurpose::Deliver,
            })
            .await
            .unwrap()
        {
            CommitResult::Acquired { lease } => lease,
            other => panic!("unexpected delivery lease: {other:?}"),
        };
        let failure = match stream
            .fail_async(
                lease,
                SafeDiagnostic {
                    code: DiagnosticCode::ExecutionRejected,
                    class: DiagnosticClass::Permanent,
                },
                StreamFailurePayload::ProtectedReference {
                    reference: "opaque-ref".into(),
                    digest: payload_digest,
                },
            )
            .await
            .unwrap()
        {
            CommitResult::Failed { failure } => failure,
            other => panic!("unexpected failure result: {other:?}"),
        };
        let skip_lease = match stream
            .apply_async(CommitIntent::Acquire {
                delivery: delivery.clone(),
                expected: expected.clone(),
                purpose: LeasePurpose::Skip,
            })
            .await
            .unwrap()
        {
            CommitResult::Acquired { lease } => lease,
            other => panic!("unexpected skip lease: {other:?}"),
        };
        let checkpoint = match stream
            .apply_async(CommitIntent::Skip {
                lease: skip_lease,
                expected,
                expected_failure_version: failure.version,
            })
            .await
            .unwrap()
        {
            CommitResult::CheckpointAdvanced { checkpoint } => checkpoint,
            other => panic!("unexpected skip result: {other:?}"),
        };
        let skipped = stream
            .failure_async(&failure.identity)
            .await
            .unwrap()
            .expect("skipped failure");
        let grant = match stream
            .apply_async(CommitIntent::Replay {
                failure: failure.identity,
                expected_version: skipped.version,
            })
            .await
            .unwrap()
        {
            CommitResult::ReplayGranted { grant } => grant,
            other => panic!("unexpected replay grant: {other:?}"),
        };
        (grant, checkpoint, delivery)
    }

    struct TestSource {
        key: CheckpointKey,
        item: Option<StreamItem>,
        polls: usize,
    }

    impl StreamSource for TestSource {
        type NextFuture<'a>
            = Ready<Result<StreamSourcePoll, SafeDiagnostic>>
        where
            Self: 'a;
        type WaitFuture<'a>
            = Ready<Result<(), SafeDiagnostic>>
        where
            Self: 'a;

        fn descriptor(&self) -> StreamSourceDescriptor {
            StreamSourceDescriptor {
                kind: StreamSourceKind::Finite,
                replayable: true,
            }
        }

        fn checkpoint_key(&self) -> CheckpointKey {
            self.key.clone()
        }

        fn failure_payload(&self, item: &StreamItem) -> StreamFailurePayload {
            StreamFailurePayload::Plaintext(item.payload.clone())
        }

        fn next<'a>(&'a mut self, _: &'a StreamCheckpoint) -> Self::NextFuture<'a> {
            self.polls += 1;
            ready(Ok(self
                .item
                .take()
                .map_or(StreamSourcePoll::Exhausted, |item| {
                    StreamSourcePoll::Item(Box::new(item))
                })))
        }

        fn wait<'a>(&'a mut self, _: &'a dyn StreamRunControl) -> Self::WaitFuture<'a> {
            ready(Ok(()))
        }
    }

    struct FirstPollCheckpointSource {
        key: CheckpointKey,
        observed: Option<StreamCheckpoint>,
    }

    impl StreamSource for FirstPollCheckpointSource {
        type NextFuture<'a>
            = Ready<Result<StreamSourcePoll, SafeDiagnostic>>
        where
            Self: 'a;
        type WaitFuture<'a>
            = Ready<Result<(), SafeDiagnostic>>
        where
            Self: 'a;

        fn descriptor(&self) -> StreamSourceDescriptor {
            StreamSourceDescriptor {
                kind: StreamSourceKind::Finite,
                replayable: true,
            }
        }

        fn checkpoint_key(&self) -> CheckpointKey {
            self.key.clone()
        }

        fn next<'a>(&'a mut self, checkpoint: &'a StreamCheckpoint) -> Self::NextFuture<'a> {
            self.observed = Some(checkpoint.clone());
            ready(Ok(StreamSourcePoll::Waiting))
        }

        fn wait<'a>(&'a mut self, _: &'a dyn StreamRunControl) -> Self::WaitFuture<'a> {
            ready(Ok(()))
        }
    }

    struct TestHandler {
        result: Option<StreamHandlerResult>,
        calls: usize,
    }

    impl StreamHandler for TestHandler {
        fn handle(&mut self, _: &StreamItem) -> StreamHandlerResult {
            self.calls += 1;
            self.result.take().unwrap_or(StreamHandlerResult::Cancelled)
        }
    }

    #[derive(Default)]
    struct MockIdempotentProvider {
        calls: AtomicUsize,
        applied_effects: AtomicUsize,
        fail_responses_until: usize,
        receipts: Mutex<BTreeMap<[u8; 32], Vec<u8>>>,
    }

    impl MockIdempotentProvider {
        fn new(fail_responses_until: usize) -> Self {
            Self {
                fail_responses_until,
                ..Self::default()
            }
        }

        fn apply_once(
            &self,
            key: ProviderEffectKey,
            effect: &StreamProviderEffect,
        ) -> Result<Vec<u8>, ProviderEffectFailure> {
            assert_eq!(effect.request(), PROVIDER_EFFECT_FIXTURE.as_bytes());
            let call = self.calls.fetch_add(1, Ordering::SeqCst);
            let receipt = {
                let mut receipts = self.receipts.lock().expect("provider receipt lock");
                receipts
                    .entry(*key.as_bytes())
                    .or_insert_with(|| {
                        self.applied_effects.fetch_add(1, Ordering::SeqCst);
                        b"fixture-provider-receipt-v1".to_vec()
                    })
                    .clone()
            };
            if call < self.fail_responses_until {
                Err(ProviderEffectFailure::OutcomeUnknown)
            } else {
                Ok(receipt)
            }
        }
    }

    struct ProviderEffectCandidateValidator {
        tables: Vec<String>,
        reject: bool,
    }

    impl StreamTableCandidateValidator for ProviderEffectCandidateValidator {
        fn tables(&self) -> &[String] {
            &self.tables
        }

        fn validate(&mut self, _: &RuntimeTableRows) -> Result<(), SafeDiagnostic> {
            if self.reject {
                Err(SafeDiagnostic {
                    code: DiagnosticCode::Internal,
                    class: DiagnosticClass::Permanent,
                })
            } else {
                Ok(())
            }
        }
    }

    struct ProviderEffectTestHandler {
        calls: usize,
        provider: Arc<MockIdempotentProvider>,
        reject_candidate: bool,
        effects: Vec<StreamProviderEffect>,
    }

    impl StreamHandler for ProviderEffectTestHandler {
        fn handle(&mut self, item: &StreamItem) -> StreamHandlerResult {
            self.calls += 1;
            self.effects = vec![
                StreamProviderEffect::new(
                    "fixture.provider",
                    "archive_event",
                    item.payload.clone(),
                )
                .expect("valid fixture provider effect"),
            ];
            StreamHandlerResult::CommitValidatedTable(StreamValidatedTableMutationBatch {
                mutations: vec![table_mutation(89, 8, Some(9))],
                next_digest: digest(88),
                validator: Box::new(ProviderEffectCandidateValidator {
                    tables: vec!["books".into()],
                    reject: self.reject_candidate && self.calls == 1,
                }),
            })
        }

        fn take_provider_effects(&mut self) -> Vec<StreamProviderEffect> {
            std::mem::take(&mut self.effects)
        }

        fn provider_effect_contract(&self, _: &str) -> ProviderEffectDeliveryContract {
            ProviderEffectDeliveryContract::IdempotentByKey
        }

        fn apply_provider_effect_once<'a>(
            &'a mut self,
            key: ProviderEffectKey,
            effect: &'a StreamProviderEffect,
        ) -> ProviderEffectFuture<'a> {
            Box::pin(std::future::ready(self.provider.apply_once(key, effect)))
        }
    }

    struct SequenceSource {
        key: CheckpointKey,
        descriptor: StreamSourceDescriptor,
        polls: usize,
        waits: usize,
        steps: VecDeque<StreamSourcePoll>,
    }

    impl StreamSource for SequenceSource {
        type NextFuture<'a>
            = Ready<Result<StreamSourcePoll, SafeDiagnostic>>
        where
            Self: 'a;
        type WaitFuture<'a>
            = Ready<Result<(), SafeDiagnostic>>
        where
            Self: 'a;

        fn descriptor(&self) -> StreamSourceDescriptor {
            self.descriptor
        }

        fn checkpoint_key(&self) -> CheckpointKey {
            self.key.clone()
        }

        fn failure_payload(&self, item: &StreamItem) -> StreamFailurePayload {
            StreamFailurePayload::Plaintext(item.payload.clone())
        }

        fn next<'a>(&'a mut self, _: &'a StreamCheckpoint) -> Self::NextFuture<'a> {
            self.polls += 1;
            ready(Ok(self
                .steps
                .pop_front()
                .unwrap_or(StreamSourcePoll::Exhausted)))
        }

        fn wait<'a>(&'a mut self, _: &'a dyn StreamRunControl) -> Self::WaitFuture<'a> {
            self.waits += 1;
            ready(Ok(()))
        }
    }

    struct DefaultPayloadSource {
        key: CheckpointKey,
        item: Option<StreamItem>,
        polls: usize,
    }

    impl StreamSource for DefaultPayloadSource {
        type NextFuture<'a>
            = Ready<Result<StreamSourcePoll, SafeDiagnostic>>
        where
            Self: 'a;
        type WaitFuture<'a>
            = Ready<Result<(), SafeDiagnostic>>
        where
            Self: 'a;

        fn descriptor(&self) -> StreamSourceDescriptor {
            StreamSourceDescriptor {
                kind: StreamSourceKind::Finite,
                replayable: true,
            }
        }

        fn checkpoint_key(&self) -> CheckpointKey {
            self.key.clone()
        }

        fn next<'a>(&'a mut self, _: &'a StreamCheckpoint) -> Self::NextFuture<'a> {
            self.polls += 1;
            ready(Ok(self
                .item
                .take()
                .map_or(StreamSourcePoll::Exhausted, |item| {
                    StreamSourcePoll::Item(Box::new(item))
                })))
        }

        fn wait<'a>(&'a mut self, _: &'a dyn StreamRunControl) -> Self::WaitFuture<'a> {
            ready(Ok(()))
        }
    }

    struct FailingSource {
        key: CheckpointKey,
        diagnostic: Option<SafeDiagnostic>,
    }

    impl StreamSource for FailingSource {
        type NextFuture<'a>
            = Ready<Result<StreamSourcePoll, SafeDiagnostic>>
        where
            Self: 'a;
        type WaitFuture<'a>
            = Ready<Result<(), SafeDiagnostic>>
        where
            Self: 'a;

        fn descriptor(&self) -> StreamSourceDescriptor {
            StreamSourceDescriptor {
                kind: StreamSourceKind::Unbounded,
                replayable: true,
            }
        }

        fn checkpoint_key(&self) -> CheckpointKey {
            self.key.clone()
        }

        fn next<'a>(&'a mut self, _: &'a StreamCheckpoint) -> Self::NextFuture<'a> {
            ready(
                self.diagnostic
                    .take()
                    .map_or(Ok(StreamSourcePoll::Exhausted), Err),
            )
        }

        fn wait<'a>(&'a mut self, _: &'a dyn StreamRunControl) -> Self::WaitFuture<'a> {
            ready(Ok(()))
        }
    }

    struct WaitingFailureSource {
        key: CheckpointKey,
        diagnostic: Option<SafeDiagnostic>,
    }

    impl StreamSource for WaitingFailureSource {
        type NextFuture<'a>
            = Ready<Result<StreamSourcePoll, SafeDiagnostic>>
        where
            Self: 'a;
        type WaitFuture<'a>
            = Ready<Result<(), SafeDiagnostic>>
        where
            Self: 'a;

        fn descriptor(&self) -> StreamSourceDescriptor {
            StreamSourceDescriptor {
                kind: StreamSourceKind::Unbounded,
                replayable: true,
            }
        }

        fn checkpoint_key(&self) -> CheckpointKey {
            self.key.clone()
        }

        fn next<'a>(&'a mut self, _: &'a StreamCheckpoint) -> Self::NextFuture<'a> {
            ready(Ok(StreamSourcePoll::Waiting))
        }

        fn wait<'a>(&'a mut self, _: &'a dyn StreamRunControl) -> Self::WaitFuture<'a> {
            ready(self.diagnostic.take().map_or(Ok(()), Err))
        }
    }

    struct BlockingWaitSource {
        key: CheckpointKey,
        wait_started: Arc<Notify>,
        polls: usize,
        waits: usize,
    }

    impl StreamSource for BlockingWaitSource {
        type NextFuture<'a>
            = Ready<Result<StreamSourcePoll, SafeDiagnostic>>
        where
            Self: 'a;
        type WaitFuture<'a>
            = Pin<Box<dyn Future<Output = Result<(), SafeDiagnostic>> + 'a>>
        where
            Self: 'a;

        fn descriptor(&self) -> StreamSourceDescriptor {
            StreamSourceDescriptor {
                kind: StreamSourceKind::Unbounded,
                replayable: true,
            }
        }

        fn checkpoint_key(&self) -> CheckpointKey {
            self.key.clone()
        }

        fn next<'a>(&'a mut self, _: &'a StreamCheckpoint) -> Self::NextFuture<'a> {
            self.polls += 1;
            ready(Ok(StreamSourcePoll::Waiting))
        }

        fn wait<'a>(&'a mut self, _: &'a dyn StreamRunControl) -> Self::WaitFuture<'a> {
            self.waits += 1;
            self.wait_started.notify_one();
            Box::pin(std::future::pending())
        }
    }

    struct DropFlag(Arc<AtomicBool>);

    impl Drop for DropFlag {
        fn drop(&mut self) {
            self.0.store(true, Ordering::Release);
        }
    }

    struct BlockingNextSource {
        key: CheckpointKey,
        next_started: Arc<Notify>,
        next_dropped: Arc<AtomicBool>,
        polls: usize,
        waits: usize,
    }

    impl StreamSource for BlockingNextSource {
        type NextFuture<'a>
            = Pin<Box<dyn Future<Output = Result<StreamSourcePoll, SafeDiagnostic>> + 'a>>
        where
            Self: 'a;
        type WaitFuture<'a>
            = Ready<Result<(), SafeDiagnostic>>
        where
            Self: 'a;

        fn descriptor(&self) -> StreamSourceDescriptor {
            StreamSourceDescriptor {
                kind: StreamSourceKind::Unbounded,
                replayable: true,
            }
        }

        fn checkpoint_key(&self) -> CheckpointKey {
            self.key.clone()
        }

        fn next<'a>(&'a mut self, _: &'a StreamCheckpoint) -> Self::NextFuture<'a> {
            self.polls += 1;
            let next_started = self.next_started.clone();
            let drop_flag = DropFlag(self.next_dropped.clone());
            Box::pin(async move {
                let _drop_flag = drop_flag;
                next_started.notify_one();
                std::future::pending::<Result<StreamSourcePoll, SafeDiagnostic>>().await
            })
        }

        fn wait<'a>(&'a mut self, _: &'a dyn StreamRunControl) -> Self::WaitFuture<'a> {
            self.waits += 1;
            ready(Ok(()))
        }
    }

    #[tokio::test]
    async fn stream_next_cancellation_interrupts_provider_at_current_checkpoint() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let delivery = stream_delivery("next-cancel", "next-cancel-next");
        let key = delivery.checkpoint_key();
        let next_started = Arc::new(Notify::new());
        let next_dropped = Arc::new(AtomicBool::new(false));
        let mut source = BlockingNextSource {
            key: key.clone(),
            next_started: next_started.clone(),
            next_dropped: next_dropped.clone(),
            polls: 0,
            waits: 0,
        };
        let mut handler = CommitHandler { calls: 0 };
        let gate = StreamRunGate::new();
        let mut run = Box::pin(state.run_stream(writer, &key, &mut source, &mut handler, &gate));
        tokio::time::timeout(Duration::from_secs(1), async {
            tokio::select! {
                _ = next_started.notified() => {}
                outcome = &mut run => panic!("stream completed before provider next: {outcome:?}"),
            }
        })
        .await
        .expect("provider next must begin before cancellation");
        assert!(gate.cancel());
        assert!(matches!(
            tokio::time::timeout(Duration::from_secs(1), &mut run)
                .await
                .expect("cancellation must interrupt a pending provider next")
                .unwrap(),
            StreamRunOutcome::Cancelled {
                delivered: 0,
                checkpoint: StreamCheckpoint {
                    version: 0,
                    committed: None,
                    ..
                }
            }
        ));
        assert!(next_dropped.load(Ordering::Acquire));
        drop(run);
        assert_eq!(source.polls, 1);
        assert_eq!(source.waits, 0);
        assert_eq!(handler.calls, 0);
        assert_eq!(state.latest_checkpoint().await.unwrap(), None);
        assert!(
            state
                .stream_backend(writer)
                .provider_failure_async(&key)
                .await
                .unwrap()
                .is_none()
        );
    }

    #[tokio::test]
    async fn stream_wait_cancellation_wakes_provider_and_preserves_checkpoint() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let delivery = stream_delivery("wait-cancel", "wait-cancel-next");
        let key = delivery.checkpoint_key();
        let wait_started = Arc::new(Notify::new());
        let mut source = BlockingWaitSource {
            key: key.clone(),
            wait_started: wait_started.clone(),
            polls: 0,
            waits: 0,
        };
        let mut handler = CommitHandler { calls: 0 };
        let gate = StreamRunGate::new();
        let mut run = Box::pin(state.run_stream(writer, &key, &mut source, &mut handler, &gate));
        tokio::select! {
            _ = wait_started.notified() => {}
            outcome = &mut run => panic!("stream completed before provider wait: {outcome:?}"),
        }
        assert!(gate.cancel());
        assert!(matches!(
            run.await.unwrap(),
            StreamRunOutcome::Cancelled {
                delivered: 0,
                checkpoint: StreamCheckpoint {
                    version: 0,
                    committed: None,
                    ..
                }
            }
        ));
        assert_eq!(source.polls, 1);
        assert_eq!(source.waits, 1);
        assert_eq!(handler.calls, 0);
    }

    struct CommitHandler {
        calls: usize,
    }

    impl StreamHandler for CommitHandler {
        fn handle(&mut self, _: &StreamItem) -> StreamHandlerResult {
            self.calls += 1;
            StreamHandlerResult::Commit(StreamMutationBatch {
                mutations: Vec::new(),
                next_digest: digest(3),
            })
        }
    }

    /// Advances the shared CWD generation while a delivery handler is open.
    /// The separate local runtime connection makes the admission/handler race
    /// deterministic without exposing a production-only test hook.
    fn advance_generation(worktree: PathBuf) {
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("worker runtime");
        runtime.block_on(async move {
            let repository = Repository::discover(worktree).expect("worker repository");
            let state = open_unmanaged_state(&repository).await;
            let writer = state.acquire_lease(id(4)).await.expect("worker writer");
            let capture = state.capture().await.expect("worker capture");
            state
                .commit(writer, &capture, &mutation(77), digest(78), &NoFault)
                .await
                .expect("worker commit");
        });
    }

    struct CaptureAdvancingCommitHandler {
        worktree: PathBuf,
        calls: usize,
    }

    impl StreamHandler for CaptureAdvancingCommitHandler {
        fn handle(&mut self, _: &StreamItem) -> StreamHandlerResult {
            self.calls += 1;
            let worktree = self.worktree.clone();
            std::thread::spawn(move || advance_generation(worktree))
                .join()
                .expect("generation-advancing worker must not panic");
            StreamHandlerResult::Commit(StreamMutationBatch {
                mutations: vec![mutation(79)],
                next_digest: digest(80),
            })
        }
    }

    struct CaptureAdvancingValidatedTableHandler {
        worktree: PathBuf,
        calls: usize,
    }

    impl StreamHandler for CaptureAdvancingValidatedTableHandler {
        fn handle(&mut self, _: &StreamItem) -> StreamHandlerResult {
            self.calls += 1;
            let worktree = self.worktree.clone();
            std::thread::spawn(move || advance_generation(worktree))
                .join()
                .expect("generation-advancing worker must not panic");
            StreamHandlerResult::CommitValidatedTable(StreamValidatedTableMutationBatch {
                mutations: vec![table_mutation(79, 1, Some(9))],
                next_digest: digest(80),
                validator: Box::new(TablesOnlyValidator {
                    tables: vec!["books".into()],
                    calls: 0,
                }),
            })
        }
    }

    #[tokio::test]
    async fn stream_admission_capture_fences_generation_advanced_by_handler() {
        let (_temp, repo) = repository();
        let worktree = repo.worktree().to_path_buf();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let delivery = stream_delivery("admission-capture", "admission-capture-next");
        let key = delivery.checkpoint_key();
        let mut source = TestSource {
            key: key.clone(),
            item: Some(StreamItem {
                delivery: delivery.clone(),
                payload: vec![1],
            }),
            polls: 0,
        };
        let mut handler = CaptureAdvancingCommitHandler { worktree, calls: 0 };

        assert!(matches!(
            state
                .run_stream_once(writer, &key, &mut source, &mut handler)
                .await,
            Err(StreamStepError::Runtime(RuntimeError::StaleCapture { .. }))
        ));
        assert_eq!(handler.calls, 1);
        assert_eq!(source.polls, 1);
        let current_capture = state.capture().await.unwrap();
        assert_eq!(current_capture.generation(), &BigInt::from(1));
        assert_eq!(current_capture.generation_digest(), digest(78));
        assert_eq!(
            state
                .stream_backend(writer)
                .checkpoint_async(&key)
                .await
                .unwrap(),
            StreamCheckpoint {
                key: key.clone(),
                version: 0,
                committed: None,
            }
        );
        let mut rows = state
            .connection
            .query(
                "SELECT mutation_id FROM pending_mutation ORDER BY sequence",
                (),
            )
            .await
            .unwrap();
        let row = rows.next().await.unwrap().unwrap();
        assert_eq!(row.get::<Vec<u8>>(0).unwrap(), id(77));
        assert!(rows.next().await.unwrap().is_none());

        let mut retry_source = TestSource {
            key: key.clone(),
            item: Some(StreamItem {
                delivery,
                payload: vec![1],
            }),
            polls: 0,
        };
        let mut retry_handler = TestHandler {
            result: Some(StreamHandlerResult::Commit(StreamMutationBatch {
                mutations: Vec::new(),
                next_digest: digest(78),
            })),
            calls: 0,
        };
        assert!(matches!(
            state
                .run_stream_once(writer, &key, &mut retry_source, &mut retry_handler)
                .await,
            Ok(StreamStep::Committed { .. })
        ));
        assert_eq!(retry_handler.calls, 1);
        assert_eq!(
            state
                .stream_backend(writer)
                .checkpoint_async(&key)
                .await
                .unwrap(),
            StreamCheckpoint {
                key,
                version: 1,
                committed: Some(Position {
                    token: Component::new("admission-capture-next").unwrap(),
                }),
            }
        );
    }

