    impl StreamFailurePayloadProvider for ReplayProvider {
        type Error = ();

        fn refetch<'a>(
            &'a self,
            _: &'a str,
        ) -> Pin<Box<dyn Future<Output = Result<Vec<u8>, Self::Error>> + 'a>> {
            Box::pin(ready(Ok(self.payload.clone())))
        }
    }

    #[derive(Clone, Copy)]
    struct CancelImmediately;

    impl StreamRunControl for CancelImmediately {
        fn cancelled(&self) -> bool {
            true
        }

        fn acquire_admission(&self) -> bool {
            false
        }

        fn release_admission(&self) {}
    }

    struct CancelAfterPoll(Cell<usize>);

    impl StreamRunControl for CancelAfterPoll {
        fn cancelled(&self) -> bool {
            let calls = self.0.get();
            self.0.set(calls + 1);
            calls > 0
        }

        fn acquire_admission(&self) -> bool {
            !self.cancelled()
        }

        fn release_admission(&self) {}
    }

    #[derive(Clone, Copy)]
    struct CancelledBeforeProviderFailure;

    impl StreamRunControl for CancelledBeforeProviderFailure {
        fn cancelled(&self) -> bool {
            true
        }

        fn acquire_admission(&self) -> bool {
            false
        }

        fn release_admission(&self) {}
    }

    struct CancelAfterWait(Cell<usize>);

    impl StreamRunControl for CancelAfterWait {
        fn cancelled(&self) -> bool {
            let calls = self.0.get();
            self.0.set(calls + 1);
            calls > 0
        }

        fn acquire_admission(&self) -> bool {
            false
        }

        fn release_admission(&self) {}
    }

    #[test]
    fn stream_run_gate_linearizes_cancellation_with_admission() {
        let gate = StreamRunGate::new();
        assert!(!gate.cancelled());
        assert!(gate.acquire_admission());
        assert!(gate.cancel());
        assert!(gate.cancelled());
        gate.release_admission();
        assert!(!gate.acquire_admission());
        assert!(!gate.cancel());
    }

    #[test]
    fn stream_run_gate_admits_one_delivery_at_a_time_and_reopens_on_release() {
        let gate = StreamRunGate::new();
        assert!(gate.acquire_admission());
        assert!(
            !gate.acquire_admission(),
            "a second admission must wait for the first to release"
        );
        gate.release_admission();
        assert!(!gate.cancelled());
        assert!(
            gate.acquire_admission(),
            "an uncancelled release reopens the gate"
        );
        gate.release_admission();

        assert!(gate.cancel());
        assert!(!gate.acquire_admission());
        gate.release_admission();
        assert!(
            gate.cancelled(),
            "releasing a gate that is not admitting must not clear cancellation"
        );
    }

    #[tokio::test]
    async fn stream_run_gate_cancel_during_admission_wakes_the_waiter() {
        let gate = StreamRunGate::new();
        assert!(
            tokio::time::timeout(Duration::from_millis(50), gate.cancellation_wait())
                .await
                .is_err(),
            "an uncancelled gate must keep the waiter parked"
        );
        assert!(gate.acquire_admission());
        assert!(gate.cancel());
        tokio::time::timeout(Duration::from_secs(1), gate.cancellation_wait())
            .await
            .expect("a cancellation requested mid-admission must wake the waiter");
    }

    #[tokio::test]
    async fn stream_runner_rejects_position_format_change_before_provider_poll() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let original = stream_delivery("format-guard", "format-guard-next").checkpoint_key();
        assert!(matches!(
            state
                .stream_backend(writer)
                .apply_async(CommitIntent::Pause {
                    key: original.clone(),
                })
                .await
                .unwrap(),
            CommitResult::StreamStatusChanged { changed: true, .. }
        ));
        let changed = CheckpointKey {
            position_format: Component::new("position-format-v2").unwrap(),
            ..original
        };
        let mut source = TestSource {
            key: changed.clone(),
            item: None,
            polls: 0,
        };
        let mut handler = CommitHandler { calls: 0 };

        let result = state
            .run_stream_once(writer, &changed, &mut source, &mut handler)
            .await;

        assert_eq!(
            result,
            Err(StreamStepError::Runtime(
                RuntimeError::StreamIdentityMismatch
            ))
        );
        assert_eq!(source.polls, 0);
        assert_eq!(handler.calls, 0);
        let mut rows = state
            .connection
            .query("SELECT COUNT(*) FROM stream_checkpoint", ())
            .await
            .unwrap();
        let row = rows.next().await.unwrap().unwrap();
        assert_eq!(row.get::<i64>(0).unwrap(), 1);
    }

    #[tokio::test]
    async fn runtime_stream_runner_repeats_until_exhaustion_and_fences_cancellation() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let first = stream_delivery("runner:one", "runner:two");
        let second = stream_delivery("runner:two", "runner:three");
        let key = first.checkpoint_key();
        let mut mismatch_source = SequenceSource {
            key: CheckpointKey {
                source: Component::new("other-source").unwrap(),
                ..key.clone()
            },
            descriptor: StreamSourceDescriptor {
                kind: StreamSourceKind::Finite,
                replayable: true,
            },
            polls: 0,
            waits: 0,
            steps: VecDeque::new(),
        };
        let mut mismatch_handler = CommitHandler { calls: 0 };
        assert_eq!(
            state
                .run_stream_once(writer, &key, &mut mismatch_source, &mut mismatch_handler,)
                .await,
            Err(StreamStepError::Runtime(
                RuntimeError::StreamIdentityMismatch
            ))
        );
        assert_eq!(mismatch_source.polls, 0);
        assert_eq!(mismatch_handler.calls, 0);
        assert_eq!(state.latest_checkpoint().await.unwrap(), None);
        let mut long_mismatch_handler = CommitHandler { calls: 0 };
        assert_eq!(
            state
                .run_stream(
                    writer,
                    &key,
                    &mut mismatch_source,
                    &mut long_mismatch_handler,
                    &NeverCancelled,
                )
                .await,
            Err(StreamStepError::Runtime(
                RuntimeError::StreamIdentityMismatch
            ))
        );
        assert_eq!(mismatch_source.polls, 0);
        assert_eq!(mismatch_source.waits, 0);
        assert_eq!(long_mismatch_handler.calls, 0);
        assert_eq!(state.latest_checkpoint().await.unwrap(), None);

        let mut source = SequenceSource {
            key: key.clone(),
            descriptor: StreamSourceDescriptor {
                kind: StreamSourceKind::Finite,
                replayable: true,
            },
            polls: 0,
            waits: 0,
            steps: VecDeque::from([
                StreamSourcePoll::Waiting,
                StreamSourcePoll::Item(Box::new(StreamItem {
                    delivery: first,
                    payload: vec![1],
                })),
                StreamSourcePoll::Item(Box::new(StreamItem {
                    delivery: second,
                    payload: vec![2],
                })),
            ]),
        };
        let mut handler = CommitHandler { calls: 0 };
        let outcome = state
            .run_stream(writer, &key, &mut source, &mut handler, &NeverCancelled)
            .await
            .unwrap();
        assert!(matches!(
            outcome,
            StreamRunOutcome::Exhausted {
                delivered: 2,
                checkpoint: StreamCheckpoint {
                    version: 2,
                    committed: Some(Position { .. }),
                    ..
                }
            }
        ));
        assert_eq!(source.polls, 4);
        assert_eq!(source.waits, 1);
        assert_eq!(handler.calls, 2);

        let mut closed_source = SequenceSource {
            key: key.clone(),
            descriptor: StreamSourceDescriptor {
                kind: StreamSourceKind::Unbounded,
                replayable: true,
            },
            polls: 0,
            waits: 0,
            steps: VecDeque::new(),
        };
        let mut closed_handler = CommitHandler { calls: 0 };
        assert!(matches!(
            state
                .run_stream(
                    writer,
                    &key,
                    &mut closed_source,
                    &mut closed_handler,
                    &NeverCancelled,
                )
                .await
                .unwrap(),
            StreamRunOutcome::Closed {
                delivered: 0,
                checkpoint: StreamCheckpoint { version: 2, .. }
            }
        ));

        let mut cancelled_source = SequenceSource {
            key: key.clone(),
            descriptor: StreamSourceDescriptor {
                kind: StreamSourceKind::Finite,
                replayable: true,
            },
            polls: 0,
            waits: 0,
            steps: VecDeque::from([StreamSourcePoll::Item(Box::new(StreamItem {
                delivery: stream_delivery("runner:three", "runner:four"),
                payload: vec![3],
            }))]),
        };
        let mut cancelled_handler = CommitHandler { calls: 0 };
        assert!(matches!(
            state
                .run_stream(
                    writer,
                    &key,
                    &mut cancelled_source,
                    &mut cancelled_handler,
                    &CancelImmediately,
                )
                .await
                .unwrap(),
            StreamRunOutcome::Cancelled {
                delivered: 0,
                checkpoint: StreamCheckpoint { version: 2, .. }
            }
        ));
        assert_eq!(cancelled_source.polls, 0);
        assert_eq!(cancelled_handler.calls, 0);

        let mut raced_source = SequenceSource {
            key: key.clone(),
            descriptor: StreamSourceDescriptor {
                kind: StreamSourceKind::Finite,
                replayable: true,
            },
            polls: 0,
            waits: 0,
            steps: VecDeque::from([StreamSourcePoll::Item(Box::new(StreamItem {
                delivery: stream_delivery("runner:three", "runner:four"),
                payload: vec![4],
            }))]),
        };
        let mut raced_handler = CommitHandler { calls: 0 };
        assert!(matches!(
            state
                .run_stream(
                    writer,
                    &key,
                    &mut raced_source,
                    &mut raced_handler,
                    &CancelAfterPoll(Cell::new(0)),
                )
                .await
                .unwrap(),
            StreamRunOutcome::Cancelled {
                delivered: 0,
                checkpoint: StreamCheckpoint { version: 2, .. }
            }
        ));
        assert_eq!(raced_source.polls, 1);
        assert_eq!(raced_handler.calls, 0);

        let mut exhaustion_race_source = SequenceSource {
            key: key.clone(),
            descriptor: StreamSourceDescriptor {
                kind: StreamSourceKind::Finite,
                replayable: true,
            },
            polls: 0,
            waits: 0,
            steps: VecDeque::new(),
        };
        let mut exhaustion_race_handler = CommitHandler { calls: 0 };
        assert!(matches!(
            state
                .run_stream(
                    writer,
                    &key,
                    &mut exhaustion_race_source,
                    &mut exhaustion_race_handler,
                    &CancelAfterPoll(Cell::new(0)),
                )
                .await
                .unwrap(),
            StreamRunOutcome::Cancelled {
                delivered: 0,
                checkpoint: StreamCheckpoint { version: 2, .. },
            }
        ));
        assert_eq!(exhaustion_race_source.polls, 1);
        assert_eq!(exhaustion_race_handler.calls, 0);
    }

