    #[tokio::test]
    async fn runtime_stream_scheduler_commits_noop_and_keeps_failures_unadvanced() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();

        let committed_delivery = stream_delivery("scheduler:commit", "scheduler:next");
        let committed_key = committed_delivery.checkpoint_key();
        let mut source = TestSource {
            key: committed_key.clone(),
            item: Some(StreamItem {
                delivery: committed_delivery,
                payload: vec![1, 2, 3],
            }),
            polls: 0,
        };
        let mut handler = TestHandler {
            result: Some(StreamHandlerResult::Commit(StreamMutationBatch {
                mutations: Vec::new(),
                next_digest: digest(3),
            })),
            calls: 0,
        };
        let committed = state
            .run_stream_once(writer, &committed_key, &mut source, &mut handler)
            .await
            .unwrap();
        assert!(matches!(
            committed,
            StreamStep::Committed {
                checkpoint: StreamCheckpoint {
                    version: 1,
                    committed: Some(Position { .. }),
                    ..
                }
            }
        ));
        assert_eq!(source.polls, 1);
        assert_eq!(handler.calls, 1);
        assert!(state.pending().await.unwrap().is_empty());
        assert_eq!(
            state
                .run_stream_once(writer, &committed_key, &mut source, &mut handler)
                .await
                .unwrap(),
            StreamStep::Exhausted
        );

        let mut failed_delivery = stream_delivery("scheduler:fail", "scheduler:after-fail");
        failed_delivery.source = Component::new("scheduler-failure-source").unwrap();
        let failed_key = failed_delivery.checkpoint_key();
        let mut failing_source = TestSource {
            key: failed_key.clone(),
            item: Some(StreamItem {
                delivery: failed_delivery.clone(),
                payload: vec![9],
            }),
            polls: 0,
        };
        let mut failing_handler = TestHandler {
            result: Some(StreamHandlerResult::Fail(SafeDiagnostic {
                code: DiagnosticCode::ExecutionRejected,
                class: DiagnosticClass::Permanent,
            })),
            calls: 0,
        };
        let before_failure = state
            .stream_backend(writer)
            .checkpoint_async(&failed_key)
            .await
            .unwrap();
        let failed = state
            .run_stream_once(
                writer,
                &failed_key,
                &mut failing_source,
                &mut failing_handler,
            )
            .await
            .unwrap();
        assert!(matches!(failed, StreamStep::Failed { .. }));
        assert_eq!(
            state
                .stream_backend(writer)
                .checkpoint_async(&failed_key)
                .await
                .unwrap(),
            before_failure
        );
        assert_eq!(failing_handler.calls, 1);

        let cancelled_delivery = stream_delivery("scheduler:cancel", "scheduler:after-cancel");
        let cancelled_key = cancelled_delivery.checkpoint_key();
        let mut cancelled_source = TestSource {
            key: cancelled_key.clone(),
            item: Some(StreamItem {
                delivery: cancelled_delivery,
                payload: vec![7],
            }),
            polls: 0,
        };
        let mut cancelled_handler = TestHandler {
            result: Some(StreamHandlerResult::Fail(SafeDiagnostic {
                code: DiagnosticCode::Cancelled,
                class: DiagnosticClass::Cancellation,
            })),
            calls: 0,
        };
        let before_cancel = state
            .stream_backend(writer)
            .checkpoint_async(&cancelled_key)
            .await
            .unwrap();
        assert!(matches!(
            state
                .run_stream_once(
                    writer,
                    &cancelled_key,
                    &mut cancelled_source,
                    &mut cancelled_handler,
                )
                .await
                .unwrap(),
            StreamStep::Cancelled { .. }
        ));
        assert_eq!(
            state
                .stream_backend(writer)
                .checkpoint_async(&cancelled_key)
                .await
                .unwrap(),
            before_cancel
        );
        assert!(
            state
                .stream_backend(writer)
                .failure_async(&FailureIdentity(stream_delivery(
                    "scheduler:cancel",
                    "scheduler:after-cancel"
                )))
                .await
                .unwrap()
                .is_none()
        );
    }

    #[tokio::test]
    async fn failed_delivery_payload_survives_runtime_reopen() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let delivery = stream_delivery("payload:one", "payload:two");
        let key = delivery.checkpoint_key();
        let payload = vec![9, 8, 7, 6];
        let diagnostic = SafeDiagnostic {
            code: DiagnosticCode::DecodeRejected,
            class: DiagnosticClass::Permanent,
        };
        let mut source = TestSource {
            key: key.clone(),
            item: Some(StreamItem {
                delivery,
                payload: payload.clone(),
            }),
            polls: 0,
        };
        let mut handler = TestHandler {
            result: Some(StreamHandlerResult::Fail(diagnostic)),
            calls: 0,
        };
        let failure = match state
            .run_stream_once(writer, &key, &mut source, &mut handler)
            .await
            .unwrap()
        {
            StreamStep::Failed { failure } => failure,
            other => panic!("unexpected stream result: {other:?}"),
        };
        assert_eq!(
            state
                .stream_backend(writer)
                .failure_payload_metadata_async(&failure.identity)
                .await
                .unwrap(),
            Some(StreamFailurePayloadMetadata {
                plaintext_bytes: Some(payload.len() as u64),
                protected_reference: false,
                redacted: true,
            })
        );
        let mut rows = state
            .connection
            .query(
                "SELECT payload FROM stream_failure_payload WHERE identity_id = ?1",
                params![stream_identity_id(&failure.identity)],
            )
            .await
            .unwrap();
        let row = rows.next().await.unwrap().expect("retained payload");
        let retained: Vec<u8> = row.get(0).unwrap();
        assert_eq!(retained, payload);
        drop(state);

        let reopened = open_state(&repo).await;
        let writer = reopened.acquire_lease(id(4)).await.unwrap();
        assert_eq!(
            reopened
                .stream_backend(writer)
                .failure_payload_metadata_async(&failure.identity)
                .await
                .unwrap(),
            Some(StreamFailurePayloadMetadata {
                plaintext_bytes: Some(payload.len() as u64),
                protected_reference: false,
                redacted: true,
            })
        );
        let mut rows = reopened
            .connection
            .query(
                "SELECT payload FROM stream_failure_payload WHERE identity_id = ?1",
                params![stream_identity_id(&failure.identity)],
            )
            .await
            .unwrap();
        let row = rows.next().await.unwrap().expect("retained payload");
        let retained: Vec<u8> = row.get(0).unwrap();
        assert_eq!(retained, payload);
    }

    #[tokio::test]
    async fn panicking_delivery_becomes_redacted_failure_and_retry_recovers() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let delivery = stream_delivery("panic-delivery", "panic-next");
        let key = delivery.checkpoint_key();
        let payload = vec![7, 8, 9];
        let mut source = TestSource {
            key: key.clone(),
            item: Some(StreamItem {
                delivery: delivery.clone(),
                payload: payload.clone(),
            }),
            polls: 0,
        };
        let mut handler = PanickingHandler { calls: 0 };
        let checkpoint_before = state
            .stream_backend(writer)
            .checkpoint_async(&key)
            .await
            .unwrap();

        let failure = match state
            .run_stream_once(writer, &key, &mut source, &mut handler)
            .await
            .unwrap()
        {
            StreamStep::Failed { failure } => failure,
            other => panic!("unexpected panicking delivery result: {other:?}"),
        };
        assert_eq!(handler.calls, 1);
        assert_eq!(failure.diagnostic.code, DiagnosticCode::Internal);
        assert_eq!(failure.diagnostic.class, DiagnosticClass::Permanent);
        assert_eq!(
            state
                .stream_backend(writer)
                .checkpoint_async(&key)
                .await
                .unwrap(),
            checkpoint_before
        );
        assert!(state.pending().await.unwrap().is_empty());
        assert!(
            load_stream_lease(&state.connection, &key)
                .await
                .unwrap()
                .is_none()
        );
        assert_eq!(
            state
                .stream_backend(writer)
                .failure_payload_metadata_async(&failure.identity)
                .await
                .unwrap(),
            Some(StreamFailurePayloadMetadata {
                plaintext_bytes: Some(payload.len() as u64),
                protected_reference: false,
                redacted: true,
            })
        );

        let retry = match state
            .stream_backend(writer)
            .apply_async(CommitIntent::Retry {
                failure: failure.identity.clone(),
                expected_version: failure.version,
                expected: (&checkpoint_before).into(),
            })
            .await
            .unwrap()
        {
            CommitResult::RetryScheduled { failure } => failure,
            other => panic!("unexpected retry result: {other:?}"),
        };
        assert_eq!(retry.status, FailureStatus::Retrying);

        let mut source = TestSource {
            key: key.clone(),
            item: Some(StreamItem { delivery, payload }),
            polls: 0,
        };
        let mut recovery_handler = CommitHandler { calls: 0 };
        assert!(matches!(
            state
                .run_stream_once(writer, &key, &mut source, &mut recovery_handler)
                .await
                .unwrap(),
            StreamStep::Committed {
                checkpoint: StreamCheckpoint { version: 1, .. }
            }
        ));
        assert_eq!(recovery_handler.calls, 1);
        let recovered = state
            .stream_backend(writer)
            .failure_async(&failure.identity)
            .await
            .unwrap()
            .expect("recovered failure");
        assert_eq!(recovered.identity, failure.identity);
        assert_eq!(recovered.status, FailureStatus::Succeeded);
    }

    #[tokio::test]
    async fn panicking_replay_returns_to_skipped_and_later_recovery_preserves_checkpoint() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let payload = vec![3, 2, 1];
        let (grant, checkpoint, delivery) = protected_replay_fixture(
            &state,
            writer,
            "panic-replay",
            Sha256::digest(&payload).into(),
        )
        .await;
        let provider = ReplayProvider {
            payload: payload.clone(),
        };
        let mut handler = PanickingHandler { calls: 0 };
        let failed = match state
            .stream_backend(writer)
            .replay_async_with_provider(grant, &provider, &mut handler)
            .await
            .unwrap()
        {
            CommitResult::ReplayFailed { failure } => failure,
            other => panic!("unexpected panicking replay result: {other:?}"),
        };
        assert_eq!(handler.calls, 1);
        assert_eq!(failed.status, FailureStatus::Skipped);
        assert_eq!(failed.diagnostic.code, DiagnosticCode::Internal);
        assert_eq!(
            state
                .stream_backend(writer)
                .checkpoint_async(&delivery.checkpoint_key())
                .await
                .unwrap(),
            checkpoint
        );
        assert!(state.pending().await.unwrap().is_empty());
        let mut claims = state
            .connection
            .query("SELECT count(*) FROM stream_replay_claim", ())
            .await
            .unwrap();
        let claim_count: i64 = claims
            .next()
            .await
            .unwrap()
            .expect("claim count")
            .get(0)
            .unwrap();
        assert_eq!(claim_count, 0);

        let next_grant = match state
            .stream_backend(writer)
            .apply_async(CommitIntent::Replay {
                failure: failed.identity.clone(),
                expected_version: failed.version,
            })
            .await
            .unwrap()
        {
            CommitResult::ReplayGranted { grant } => grant,
            other => panic!("unexpected recovery replay result: {other:?}"),
        };
        let mut recovery_handler = ReplayHandler {
            payload: Vec::new(),
            result: Some(StreamHandlerResult::Commit(StreamMutationBatch {
                mutations: Vec::new(),
                next_digest: digest(3),
            })),
        };
        let recovered = match state
            .stream_backend(writer)
            .replay_async_with_provider(next_grant, &provider, &mut recovery_handler)
            .await
            .unwrap()
        {
            CommitResult::ReplayCompleted { failure } => failure,
            other => panic!("unexpected replay recovery result: {other:?}"),
        };
        assert_eq!(recovered.status, FailureStatus::Replayed);
        assert_eq!(recovery_handler.payload, payload);
        let mut claims = state
            .connection
            .query("SELECT count(*) FROM stream_replay_claim", ())
            .await
            .unwrap();
        let claim_count: i64 = claims
            .next()
            .await
            .unwrap()
            .expect("claim count")
            .get(0)
            .unwrap();
        assert_eq!(claim_count, 0);
        assert_eq!(
            state
                .stream_backend(writer)
                .checkpoint_async(&delivery.checkpoint_key())
                .await
                .unwrap(),
            checkpoint
        );
    }

