    #[tokio::test]
    async fn keyed_source_without_payload_policy_fails_closed_and_releases_lease() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let delivery = stream_delivery("legacy:one", "legacy:two");
        let key = delivery.checkpoint_key();
        let capture = state.capture().await.unwrap();
        let checkpoint = state.stream_checkpoint(&key).await.unwrap();
        let mut source = DefaultPayloadSource {
            key: key.clone(),
            item: Some(StreamItem {
                delivery: delivery.clone(),
                payload: vec![1, 2, 3],
            }),
            polls: 0,
        };
        let mut handler = TestHandler {
            result: Some(StreamHandlerResult::Fail(SafeDiagnostic {
                code: DiagnosticCode::DecodeRejected,
                class: DiagnosticClass::Permanent,
            })),
            calls: 0,
        };
        assert_eq!(
            state
                .run_stream_once(writer, &key, &mut source, &mut handler)
                .await,
            Err(StreamStepError::Runtime(RuntimeError::RecoveryInvalid))
        );
        assert_eq!(source.polls, 1);
        assert_eq!(handler.calls, 0);
        assert_eq!(state.capture().await.unwrap(), capture);
        assert_eq!(state.stream_checkpoint(&key).await.unwrap(), checkpoint);
        assert!(state.pending().await.unwrap().is_empty());
        assert_eq!(
            state.committed_table_row("books", &[1]).await.unwrap(),
            None
        );
        let mut stream = state.stream_backend(writer);
        assert!(
            stream
                .failure_async(&FailureIdentity(delivery.clone()))
                .await
                .unwrap()
                .is_none()
        );
        assert!(matches!(
            stream
                .apply_async(CommitIntent::Acquire {
                    delivery,
                    expected: CheckpointPrecondition::from(&checkpoint),
                    purpose: LeasePurpose::Deliver,
                })
                .await
                .unwrap(),
            CommitResult::Acquired { .. }
        ));
    }

    #[tokio::test]
    async fn invalid_failure_payload_is_owner_fenced_before_validation() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let old = state.acquire_lease(id(4)).await.unwrap();
        let mut old_backend = state.stream_backend(old);
        let delivery = stream_delivery("invalid-owner", "invalid-next");
        let lease = match old_backend
            .apply_async(CommitIntent::Acquire {
                delivery,
                expected: orna_stream::CheckpointPrecondition {
                    version: 0,
                    committed: None,
                },
                purpose: LeasePurpose::Deliver,
            })
            .await
            .unwrap()
        {
            CommitResult::Acquired { lease } => lease,
            other => panic!("unexpected stream acquire result: {other:?}"),
        };
        let replacement = state.recover_abandoned(id(4), id(5)).await.unwrap();
        assert_eq!(
            old_backend
                .fail_async(
                    lease.clone(),
                    SafeDiagnostic {
                        code: DiagnosticCode::DecodeRejected,
                        class: DiagnosticClass::Permanent,
                    },
                    StreamFailurePayload::ProtectedReference {
                        reference: String::new(),
                        digest: [3; 32],
                    },
                )
                .await,
            Err(RuntimeError::OwnerLost)
        );
        let mut replacement_backend = state.stream_backend(replacement);
        assert!(matches!(
            replacement_backend
                .apply_async(CommitIntent::Acquire {
                    delivery: lease.delivery,
                    expected: orna_stream::CheckpointPrecondition {
                        version: 0,
                        committed: None,
                    },
                    purpose: LeasePurpose::Deliver,
                })
                .await
                .unwrap(),
            CommitResult::Acquired { .. }
        ));
    }

    #[tokio::test]
    async fn recovery_reopens_an_interrupted_retry_after_releasing_its_lease() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let delivery = stream_delivery("retry-recovery", "retry-recovery-next");
        let expected = orna_stream::CheckpointPrecondition {
            version: 0,
            committed: None,
        };
        let diagnostic = SafeDiagnostic {
            code: DiagnosticCode::DecodeRejected,
            class: DiagnosticClass::Permanent,
        };
        let retrying = {
            let mut stream = state.stream_backend(writer);
            let lease = match stream
                .apply_async(CommitIntent::Acquire {
                    delivery: delivery.clone(),
                    expected: expected.clone(),
                    purpose: LeasePurpose::Deliver,
                })
                .await
                .unwrap()
            {
                CommitResult::Acquired { lease } => lease,
                other => panic!("unexpected stream acquire result: {other:?}"),
            };
            let failed = match stream
                .fail_async(
                    lease,
                    diagnostic,
                    StreamFailurePayload::Plaintext(vec![1, 2, 3]),
                )
                .await
                .unwrap()
            {
                CommitResult::Failed { failure } => failure,
                other => panic!("unexpected stream failure result: {other:?}"),
            };
            match stream
                .apply_async(CommitIntent::Retry {
                    failure: failed.identity,
                    expected_version: failed.version,
                    expected: expected.clone(),
                })
                .await
                .unwrap()
            {
                CommitResult::RetryScheduled { failure, .. } => failure,
                other => panic!("unexpected stream retry result: {other:?}"),
            }
        };
        assert_eq!(retrying.status, FailureStatus::Retrying);
        assert_eq!(retrying.attempts, 2);

        let replacement = state.recover_abandoned(id(4), id(5)).await.unwrap();
        let mut stream = state.stream_backend(replacement);
        let recovered = stream
            .failure_async(&retrying.identity)
            .await
            .unwrap()
            .expect("recovered failure");
        assert_eq!(recovered.status, FailureStatus::Failed);
        assert_eq!(recovered.version, retrying.version + 1);
        assert_eq!(recovered.attempts, 2);
        assert!(matches!(
            stream
                .apply_async(CommitIntent::Retry {
                    failure: recovered.identity,
                    expected_version: recovered.version,
                    expected,
                })
                .await
                .unwrap(),
            CommitResult::RetryScheduled { .. }
        ));
    }

    #[tokio::test]
    async fn recovery_refuses_retry_with_missing_or_mismatched_durable_evidence() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let delivery = stream_delivery("retry-recovery-claim", "retry-recovery-next");
        let expected = CheckpointPrecondition {
            version: 0,
            committed: None,
        };
        let retrying = {
            let mut stream = state.stream_backend(writer);
            let lease = match stream
                .apply_async(CommitIntent::Acquire {
                    delivery: delivery.clone(),
                    expected: expected.clone(),
                    purpose: LeasePurpose::Deliver,
                })
                .await
                .unwrap()
            {
                CommitResult::Acquired { lease } => lease,
                other => panic!("unexpected stream acquire result: {other:?}"),
            };
            let failed = match stream
                .fail_async(
                    lease,
                    SafeDiagnostic {
                        code: DiagnosticCode::DecodeRejected,
                        class: DiagnosticClass::Permanent,
                    },
                    StreamFailurePayload::Plaintext(vec![1, 2, 3]),
                )
                .await
                .unwrap()
            {
                CommitResult::Failed { failure } => failure,
                other => panic!("unexpected stream failure result: {other:?}"),
            };
            match stream
                .apply_async(CommitIntent::Retry {
                    failure: failed.identity,
                    expected_version: failed.version,
                    expected,
                })
                .await
                .unwrap()
            {
                CommitResult::RetryScheduled { failure } => failure,
                other => panic!("unexpected stream retry result: {other:?}"),
            }
        };
        state.validate_recovery().await.unwrap();
        state
            .connection
            .execute(
                "UPDATE stream_retry_claim SET identity_id = ?2 WHERE key_id = ?1",
                params![
                    stream_key_id(&delivery.checkpoint_key()),
                    "mismatched-retry-claim"
                ],
            )
            .await
            .unwrap();

        assert_eq!(
            state.validate_recovery().await,
            Err(RuntimeError::RecoveryInvalid)
        );
        state
            .connection
            .execute(
                "UPDATE stream_retry_claim SET identity_id = ?2 WHERE key_id = ?1",
                params![
                    stream_key_id(&delivery.checkpoint_key()),
                    stream_identity_id(&retrying.identity)
                ],
            )
            .await
            .unwrap();
        state
            .connection
            .execute(
                "DELETE FROM stream_lease WHERE key_id = ?1",
                params![stream_key_id(&delivery.checkpoint_key())],
            )
            .await
            .unwrap();
        assert_eq!(
            state.validate_recovery().await,
            Err(RuntimeError::RecoveryInvalid)
        );
        assert_eq!(
            state.recover_abandoned(id(4), id(5)).await,
            Err(RuntimeError::RecoveryInvalid)
        );
        assert_eq!(state.current_lease().await.unwrap(), Some(writer));
        assert_eq!(
            state
                .stream_backend(writer)
                .failure_async(&retrying.identity)
                .await
                .unwrap()
                .expect("retry remains fenced")
                .status,
            FailureStatus::Retrying
        );
        drop(state);
        assert!(matches!(
            RuntimeState::open(
                &repo,
                RuntimeIdentity {
                    database_id: id(1),
                    repository_id: id(2),
                },
                digest(3),
            )
            .await,
            Err(RuntimeError::RecoveryInvalid)
        ));
    }

    #[tokio::test]
    async fn reopen_recovers_an_acquired_retry_without_advancing_or_rekeying_failure() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let delivery = stream_delivery("retry-reopen", "retry-reopen-next");
        let expected = CheckpointPrecondition {
            version: 0,
            committed: None,
        };
        let retrying = {
            let mut stream = state.stream_backend(writer);
            let lease = match stream
                .apply_async(CommitIntent::Acquire {
                    delivery: delivery.clone(),
                    expected: expected.clone(),
                    purpose: LeasePurpose::Deliver,
                })
                .await
                .unwrap()
            {
                CommitResult::Acquired { lease } => lease,
                other => panic!("unexpected stream acquire result: {other:?}"),
            };
            let failed = match stream
                .fail_async(
                    lease,
                    SafeDiagnostic {
                        code: DiagnosticCode::DecodeRejected,
                        class: DiagnosticClass::Permanent,
                    },
                    StreamFailurePayload::Plaintext(vec![1, 2, 3]),
                )
                .await
                .unwrap()
            {
                CommitResult::Failed { failure } => failure,
                other => panic!("unexpected stream failure result: {other:?}"),
            };
            match stream
                .apply_async(CommitIntent::Retry {
                    failure: failed.identity,
                    expected_version: failed.version,
                    expected: expected.clone(),
                })
                .await
                .unwrap()
            {
                CommitResult::RetryScheduled { failure } => failure,
                other => panic!("unexpected stream retry result: {other:?}"),
            }
        };
        let acquired = match state
            .stream_backend(writer)
            .apply_async(CommitIntent::Acquire {
                delivery: delivery.clone(),
                expected: expected.clone(),
                purpose: LeasePurpose::Deliver,
            })
            .await
            .unwrap()
        {
            CommitResult::Acquired { lease } => lease,
            other => panic!("unexpected acquired retry: {other:?}"),
        };
        assert_eq!(acquired.delivery, delivery);
        let stale_version = retrying.version;
        drop(state);

        let reopened = open_state(&repo).await;
        let replacement = reopened.recover_abandoned(id(4), id(5)).await.unwrap();
        let mut stream = reopened.stream_backend(replacement);
        let recovered = stream
            .failure_async(&retrying.identity)
            .await
            .unwrap()
            .expect("recovered failure");
        assert_eq!(recovered.identity, retrying.identity);
        assert_eq!(recovered.status, FailureStatus::Failed);
        assert_eq!(recovered.version, stale_version + 1);
        assert_eq!(recovered.attempts, retrying.attempts);
        assert_eq!(
            stream
                .checkpoint_async(&delivery.checkpoint_key())
                .await
                .unwrap(),
            StreamCheckpoint {
                key: delivery.checkpoint_key(),
                version: expected.version,
                committed: expected.committed.clone(),
            }
        );
        assert_eq!(
            stream
                .apply_async(CommitIntent::Retry {
                    failure: recovered.identity.clone(),
                    expected_version: stale_version,
                    expected: expected.clone(),
                })
                .await
                .unwrap(),
            CommitResult::Rejected(RejectReason::StaleFailure)
        );
        assert!(matches!(
            stream
                .apply_async(CommitIntent::Retry {
                    failure: recovered.identity,
                    expected_version: recovered.version,
                    expected,
                })
                .await
                .unwrap(),
            CommitResult::RetryScheduled { .. }
        ));
    }

    #[tokio::test]
    async fn cancelled_retry_keeps_the_stable_failure_blocking_and_checkpoint_unadvanced() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let failed_delivery = stream_delivery("retry-cancelled", "retry-cancelled-next");
        let later_delivery = stream_delivery("later-delivery", "later-delivery-next");
        let expected = CheckpointPrecondition {
            version: 0,
            committed: None,
        };
        let diagnostic = SafeDiagnostic {
            code: DiagnosticCode::ExecutionRejected,
            class: DiagnosticClass::Permanent,
        };
        let mut stream = state.stream_backend(writer);
        let lease = match stream
            .apply_async(CommitIntent::Acquire {
                delivery: failed_delivery.clone(),
                expected: expected.clone(),
                purpose: LeasePurpose::Deliver,
            })
            .await
            .unwrap()
        {
            CommitResult::Acquired { lease } => lease,
            other => panic!("unexpected delivery lease: {other:?}"),
        };
        let failed = match stream
            .fail_async(
                lease,
                diagnostic,
                StreamFailurePayload::Plaintext(vec![1, 2, 3]),
            )
            .await
            .unwrap()
        {
            CommitResult::Failed { failure } => failure,
            other => panic!("unexpected failure result: {other:?}"),
        };
        assert_eq!(
            stream
                .apply_async(CommitIntent::Acquire {
                    delivery: later_delivery.clone(),
                    expected: expected.clone(),
                    purpose: LeasePurpose::Deliver,
                })
                .await
                .unwrap(),
            CommitResult::Rejected(RejectReason::BlockingFailure)
        );
        let retrying = match stream
            .apply_async(CommitIntent::Retry {
                failure: failed.identity.clone(),
                expected_version: failed.version,
                expected: expected.clone(),
            })
            .await
            .unwrap()
        {
            CommitResult::RetryScheduled { failure } => failure,
            other => panic!("unexpected retry result: {other:?}"),
        };
        let retry_lease = match stream
            .apply_async(CommitIntent::Acquire {
                delivery: failed_delivery.clone(),
                expected: expected.clone(),
                purpose: LeasePurpose::Deliver,
            })
            .await
            .unwrap()
        {
            CommitResult::Acquired { lease } => lease,
            other => panic!("unexpected retry lease: {other:?}"),
        };
        assert!(matches!(
            stream
                .apply_async(CommitIntent::Cancel { lease: retry_lease })
                .await
                .unwrap(),
            CommitResult::Cancelled { .. }
        ));
        let checkpoint = stream
            .checkpoint_async(&failed_delivery.checkpoint_key())
            .await
            .unwrap();
        assert_eq!(checkpoint.version, expected.version);
        assert_eq!(checkpoint.committed, expected.committed);
        let recovered = stream
            .failure_async(&failed.identity)
            .await
            .unwrap()
            .expect("stable failure after cancellation");
        assert_eq!(recovered.identity, failed.identity);
        assert_eq!(recovered.status, FailureStatus::Failed);
        assert_eq!(recovered.attempts, retrying.attempts);
        assert_eq!(recovered.version, retrying.version + 1);
        assert_eq!(
            stream
                .apply_async(CommitIntent::Acquire {
                    delivery: later_delivery,
                    expected,
                    purpose: LeasePurpose::Deliver,
                })
                .await
                .unwrap(),
            CommitResult::Rejected(RejectReason::BlockingFailure)
        );
    }

