    #[tokio::test]
    async fn replay_executes_retained_payload_without_advancing_live_checkpoint() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let delivery = stream_delivery("replay", "replay-next");
        let expected = orna_stream::CheckpointPrecondition {
            version: 0,
            committed: None,
        };
        let (grant, checkpoint) = {
            let mut stream = state.stream_backend(writer);
            let lease = match stream
                .apply_async(CommitIntent::Acquire {
                    delivery: delivery.clone(),
                    expected: expected.clone(),
                    purpose: LeasePurpose::Deliver,
                })
                .await
                .unwrap()
            {
                CommitResult::Acquired { lease } => lease,
                other => panic!("unexpected delivery lease: {other:?}"),
            };
            let failure = match stream
                .fail_async(
                    lease,
                    SafeDiagnostic {
                        code: DiagnosticCode::ExecutionRejected,
                        class: DiagnosticClass::Permanent,
                    },
                    StreamFailurePayload::Plaintext(vec![7, 8]),
                )
                .await
                .unwrap()
            {
                CommitResult::Failed { failure } => failure,
                other => panic!("unexpected failure result: {other:?}"),
            };
            let skip_lease = match stream
                .apply_async(CommitIntent::Acquire {
                    delivery: delivery.clone(),
                    expected: expected.clone(),
                    purpose: LeasePurpose::Skip,
                })
                .await
                .unwrap()
            {
                CommitResult::Acquired { lease } => lease,
                other => panic!("unexpected skip lease: {other:?}"),
            };
            let checkpoint = match stream
                .apply_async(CommitIntent::Skip {
                    lease: skip_lease,
                    expected,
                    expected_failure_version: failure.version,
                })
                .await
                .unwrap()
            {
                CommitResult::CheckpointAdvanced { checkpoint } => checkpoint,
                other => panic!("unexpected skip result: {other:?}"),
            };
            let skipped = stream
                .failure_async(&failure.identity)
                .await
                .unwrap()
                .expect("skipped failure");
            let grant = match stream
                .apply_async(CommitIntent::Replay {
                    failure: failure.identity,
                    expected_version: skipped.version,
                })
                .await
                .unwrap()
            {
                CommitResult::ReplayGranted { grant } => grant,
                other => panic!("unexpected replay grant: {other:?}"),
            };
            (grant, checkpoint)
        };
        let mut handler = ReplayHandler {
            payload: Vec::new(),
            result: Some(StreamHandlerResult::Commit(StreamMutationBatch {
                mutations: vec![mutation(9)],
                next_digest: digest(10),
            })),
        };
        let result = state
            .stream_backend(writer)
            .replay_async(grant, &mut handler)
            .await
            .unwrap();
        let replayed = match result {
            CommitResult::ReplayCompleted { failure } => failure,
            other => panic!("unexpected replay result: {other:?}"),
        };
        assert_eq!(replayed.status, FailureStatus::Replayed);
        assert_eq!(handler.payload, vec![7, 8]);
        assert_eq!(state.pending().await.unwrap(), vec![mutation(9)]);
        assert_eq!(
            state
                .stream_backend(writer)
                .checkpoint_async(&delivery.checkpoint_key())
                .await
                .unwrap(),
            checkpoint
        );
    }

    #[tokio::test]
    async fn direct_replay_completion_requires_execution_claim_but_replay_async_succeeds() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let payload = b"claim-required-payload".to_vec();
        let payload_digest: [u8; 32] = Sha256::digest(&payload).into();
        let (grant, checkpoint, delivery) =
            protected_replay_fixture(&state, writer, "claim-required", payload_digest).await;
        let capture = state.capture().await.unwrap();
        let empty_mutations = Vec::new();
        let empty_table_mutations = Vec::new();

        assert_eq!(
            state
                .commit_stream_replay(StreamReplayCommit {
                    writer,
                    expected_capture: &capture,
                    mutations: &empty_mutations,
                    next_digest: capture.generation_digest(),
                    grant: grant.clone(),
                    faults: &NoFault,
                })
                .await,
            Err(RuntimeError::RecoveryInvalid)
        );
        assert_eq!(state.capture().await.unwrap(), capture);
        assert_eq!(
            state
                .stream_backend(writer)
                .checkpoint_async(&delivery.checkpoint_key())
                .await
                .unwrap(),
            checkpoint
        );
        assert_eq!(
            state
                .stream_backend(writer)
                .failure_async(&grant.failure)
                .await
                .unwrap()
                .expect("replay failure remains retained")
                .status,
            FailureStatus::Replaying
        );

        let raw_result = {
            let mut stream = state.stream_backend(writer);
            stream
                .apply_async(CommitIntent::ReplayComplete {
                    failure: grant.failure.clone(),
                    expected_version: grant.version,
                })
                .await
        };
        assert_eq!(raw_result, Err(RuntimeError::RecoveryInvalid));

        let mut validator = TablesOnlyValidator {
            tables: vec!["books".into()],
            calls: 0,
        };
        assert!(matches!(
            state
                .commit_stream_validated_table_replay(StreamValidatedTableReplayCommit {
                    writer,
                    expected_capture: &capture,
                    mutations: &empty_table_mutations,
                    next_digest: capture.generation_digest(),
                    grant: grant.clone(),
                    validator: &mut validator,
                    faults: &NoFault,
                })
                .await,
            Err(StreamTableDeliveryError::Runtime(
                RuntimeError::RecoveryInvalid
            ))
        ));
        assert_eq!(validator.calls, 0);

        let provider = ReplayProvider {
            payload: payload.clone(),
        };
        let mut handler = ReplayHandler {
            payload: Vec::new(),
            result: Some(StreamHandlerResult::Commit(StreamMutationBatch {
                mutations: empty_mutations,
                next_digest: capture.generation_digest(),
            })),
        };
        let result = state
            .stream_backend(writer)
            .replay_async_with_provider(grant, &provider, &mut handler)
            .await
            .unwrap();
        let replayed = match result {
            CommitResult::ReplayCompleted { failure } => failure,
            other => panic!("unexpected replay result: {other:?}"),
        };
        assert_eq!(replayed.status, FailureStatus::Replayed);
        assert_eq!(handler.payload, payload);
        assert_eq!(
            state
                .stream_backend(writer)
                .checkpoint_async(&delivery.checkpoint_key())
                .await
                .unwrap(),
            checkpoint
        );
    }

    #[tokio::test]
    async fn public_replay_cancel_preserves_an_active_handler_claim() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let writer = state.acquire_lease(id(4)).await.unwrap();
        let (grant, checkpoint, _) =
            protected_replay_fixture(&state, writer, "replay-cancel-claim", digest(5)).await;
        state
            .claim_stream_replay(writer, &grant)
            .await
            .unwrap()
            .unwrap();
        let before = state
            .stream_backend(writer)
            .failure_async(&grant.failure)
            .await
            .unwrap()
            .expect("admitted replay failure");

        assert_eq!(
            state
                .stream_backend(writer)
                .apply_async(CommitIntent::ReplayCancel {
                    failure: grant.failure.clone(),
                    expected_version: grant.version,
                })
                .await
                .unwrap(),
            CommitResult::Rejected(RejectReason::LeaseAlreadyHeld)
        );
        assert_eq!(
            state
                .stream_backend(writer)
                .failure_async(&grant.failure)
                .await
                .unwrap(),
            Some(before)
        );
        assert_eq!(
            load_stream_replay_claim(&state.connection, &grant.failure)
                .await
                .unwrap(),
            Some(StoredStreamReplayClaim {
                version: grant.version,
                owner: writer,
            })
        );
        assert_eq!(
            state
                .stream_backend(writer)
                .checkpoint_async(&grant.failure.0.checkpoint_key())
                .await
                .unwrap(),
            checkpoint
        );
    }

