    #[tokio::test]
    async fn admission_capability_is_not_reissued_after_reopen() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let original = state.acquire_lease(id(32)).await.unwrap();
        let identity = request(33, 34);
        let fingerprint = digest(35);
        let (reserved, capability) = state
            .reserve_request_with_admission(identity, fingerprint)
            .await
            .unwrap();
        let stale_capability = capability.expect("fresh owner-bound capability");
        assert_eq!(reserved.state, RequestState::Reserved);
        assert!(state.run_observations().await.unwrap().is_empty());
        drop(state);

        let reopened = open_state(&repo).await;
        let abandoned = reopened
            .current_lease()
            .await
            .unwrap()
            .expect("original writer remains durable across reopen");
        assert_eq!(abandoned, original);
        let current = reopened.takeover_lease(abandoned, id(36)).await.unwrap();

        let (reopened_status, reissued_capability) = reopened
            .reserve_request_with_admission(identity, fingerprint)
            .await
            .unwrap();
        assert_eq!(reopened_status, reserved);
        assert!(reissued_capability.is_none());

        let registration = RunObservationRegistration {
            request: identity,
            consumer_identity: stream_delivery("reopen-admission", "begin").consumer,
            function: "pkg.reopen_admission".into(),
            source_identity: Some("source reopen admission".into()),
            invocation_id: id(37),
        };
        assert_eq!(
            reopened
                .start_request_with_owner_and_admission(
                    identity,
                    fingerprint,
                    current,
                    stale_capability.clone(),
                )
                .await,
            Err(RuntimeError::RequestOwnerConflict)
        );
        assert_eq!(
            reopened
                .begin_observed_request_with_admission(
                    registration,
                    fingerprint,
                    current,
                    stale_capability,
                )
                .await,
            Err(RuntimeError::RequestOwnerConflict)
        );
        assert_eq!(
            reopened
                .request_status(identity, fingerprint)
                .await
                .unwrap()
                .unwrap()
                .state,
            RequestState::Reserved
        );
        assert!(reopened.run_observations().await.unwrap().is_empty());
    }

    #[tokio::test]
    async fn session_deletion_fence_blocks_external_reservation_until_terminal() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let external = open_state(&repo).await;
        let owner = state.acquire_lease(id(4)).await.unwrap();
        let active = request(5, 6);
        let active_fingerprint = digest(7);
        state
            .reserve_request(active, active_fingerprint)
            .await
            .unwrap();

        state.begin_session_deletion(id(5), owner).await.unwrap();
        state.begin_session_deletion(id(5), owner).await.unwrap();
        assert_eq!(
            external.reserve_request(request(5, 8), digest(9)).await,
            Err(RuntimeError::LeaseHeld)
        );
        assert_eq!(
            state.reserve_request(request(5, 8), digest(9)).await,
            Err(RuntimeError::SessionClosed)
        );
        assert_eq!(
            state.finish_session_deletion(id(5), owner).await,
            Err(RuntimeError::SessionWorkActive)
        );
        assert_eq!(
            state
                .finish_session_deletion(
                    id(5),
                    WriterLease {
                        owner_id: id(9),
                        epoch: owner.epoch,
                    },
                )
                .await,
            Err(RuntimeError::OwnerLost)
        );

        state
            .cancel_request_with_owner(active, active_fingerprint, owner, outcome(10))
            .await
            .unwrap();
        state.finish_session_deletion(id(5), owner).await.unwrap();
        state.finish_session_deletion(id(5), owner).await.unwrap();
        assert_eq!(
            external.reserve_request(request(5, 11), digest(12)).await,
            Err(RuntimeError::LeaseHeld)
        );
        assert_eq!(
            state.reserve_request(request(5, 11), digest(12)).await,
            Err(RuntimeError::SessionClosed)
        );

        drop(external);
        drop(state);
        let reopened = open_state(&repo).await;
        assert_eq!(
            reopened.reserve_request(request(5, 13), digest(14)).await,
            Err(RuntimeError::SessionClosed)
        );
    }

