    #[tokio::test]
    async fn current_runtime_view_is_owner_generation_fenced_and_coherent() {
        let (_temp, repo) = repository();
        let state = open_state(&repo).await;
        let request = request(201, 202);
        let key = stream_delivery("current", "view").checkpoint_key();
        state.reserve_request(request, digest(203)).await.unwrap();
        let run = state
            .register_run_observation(RunObservationRegistration {
                request,
                consumer_identity: key.consumer.clone(),
                function: "pkg.current".into(),
                source_identity: None,
                invocation_id: id(204),
            })
            .await
            .unwrap();
        let stream = state
            .register_stream_observation(StreamObservationRegistration {
                run: run.id,
                producer: "source-object".into(),
                consumer: None,
                checkpoint: key,
            })
            .await
            .unwrap();
        let owner = state.acquire_lease(id(205)).await.unwrap();
        let fence = state.runtime_observation_fence(owner).await.unwrap();
        let view = state.current_runtime_observations(&fence).await.unwrap();
        assert_eq!(view.capture, *fence.capture());
        assert_eq!(
            view.runs.iter().map(|row| row.id).collect::<Vec<_>>(),
            vec![run.id]
        );
        assert_eq!(
            view.streams.iter().map(|row| row.id).collect::<Vec<_>>(),
            vec![stream.id]
        );
        assert_eq!(view.streams[0].run, view.runs[0].id);
        let projections = state.current_runtime_sys_projections(&fence).await.unwrap();
        assert_eq!(projections.capture, *fence.capture());
        assert_eq!(
            projections
                .runs
                .iter()
                .map(|row| row.id)
                .collect::<Vec<_>>(),
            vec![run.id.as_bytes()]
        );
        assert_eq!(projections.streams.len(), 1);
        assert!(projections.runs[0].live);
        assert!(projections.streams[0].live);
        let mut terminal_run = view.runs[0].clone();
        terminal_run.status = RunObservationStatus::Completed;
        terminal_run.ended_ms = Some(terminal_run.started_ms);
        assert_eq!(
            SysRunProjection::try_from(&terminal_run),
            Err(RuntimeError::RecoveryInvalid)
        );
        let mut terminal_stream = view.streams[0].clone();
        terminal_stream.status = StreamObservationStatus::Completed;
        assert_eq!(
            SysStreamProjection::try_from_observation(&terminal_stream, &view.runs[0]),
            Err(RuntimeError::RecoveryInvalid)
        );
        let mut historical_stream = view.streams[0].clone();
        historical_stream.live = false;
        assert!(
            !SysStreamProjection::try_from_observation(&historical_stream, &view.runs[0])
                .unwrap()
                .live
        );
        assert_eq!(projections.streams[0].run, projections.runs[0].reference);
        assert_eq!(
            project_current_runtime_observations(RuntimeObservationView {
                capture: view.capture.clone(),
                runs: Vec::new(),
                queries: Vec::new(),
                streams: view.streams.clone(),
            }),
            Err(RuntimeError::ObservationCoordinateMismatch)
        );
        let mut historical_run = view.runs[0].clone();
        historical_run.live = false;
        assert_eq!(
            project_current_runtime_observations(RuntimeObservationView {
                capture: view.capture.clone(),
                runs: vec![historical_run],
                queries: Vec::new(),
                streams: Vec::new(),
            }),
            Err(RuntimeError::RecoveryInvalid)
        );
        assert_eq!(
            project_current_runtime_observations(RuntimeObservationView {
                capture: view.capture.clone(),
                runs: view.runs.clone(),
                queries: Vec::new(),
                streams: vec![historical_stream],
            }),
            Err(RuntimeError::RecoveryInvalid)
        );
        let mut malformed_run = view.runs[0].clone();
        malformed_run.runtime_id = id(206);
        assert_eq!(
            project_current_runtime_observations(RuntimeObservationView {
                capture: view.capture.clone(),
                queries: Vec::new(),
                runs: vec![malformed_run],
                streams: Vec::new(),
            }),
            Err(RuntimeError::InvalidObservationReference)
        );

        assert_eq!(
            state
                .runtime_observation_fence(WriterLease {
                    owner_id: id(206),
                    epoch: owner.epoch,
                })
                .await,
            Err(RuntimeError::OwnerLost)
        );

        let capture = state.capture().await.unwrap();
        state
            .commit(owner, &capture, &mutation(207), digest(208), &NoFault)
            .await
            .unwrap();
        assert!(matches!(
            state.current_runtime_observations(&fence).await,
            Err(RuntimeError::StaleCapture { .. })
        ));
        assert!(matches!(
            state.current_runtime_sys_projections(&fence).await,
            Err(RuntimeError::StaleCapture { .. })
        ));
        assert_eq!(state.run_observations().await.unwrap().len(), 1);
        assert_eq!(state.stream_observations().await.unwrap().len(), 1);

        let current = state.runtime_observation_fence(owner).await.unwrap();
        let current_view = state.current_runtime_observations(&current).await.unwrap();
        assert!(current_view.runs.is_empty());
        assert!(current_view.streams.is_empty());
        let current_projections = state
            .current_runtime_sys_projections(&current)
            .await
            .unwrap();
        assert!(current_projections.runs.is_empty());
        assert!(current_projections.streams.is_empty());
    }

